// Synthetic committed-tree fixtures for the Phase 253 registration runner contracts.
//
// Everything here is TEST-ONLY. The helper builds a temporary Git repository, commits
// the sources the real verifier binds to, and writes internally consistent synthetic
// freeze / evidence / log / native-report files. It never copies or reads the active
// GSD phase records or refs, opens no socket, and starts no server, browser or database.
// Every artifact carries the `synthetic-native-fixture` provenance marker, which the live
// accepted-only predicates in ci-registration-recovery.mjs reject.
import crypto from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

export const SYNTHETIC_LABEL = 'synthetic-native-fixture/v1';
export const FIXTURE_PHASE_DIR = '.planning/phases/253-fix-flaky-ci-and-preserve-required-checks';
export const SELECTED_TITLE = 'render bundle: board-mg-9/populated';
export const FIXTURE_PROJECTS = ['admin-eval', 'admin-eval-mobile', 'admin-eval-dark'];
export const FIXTURE_IDENTITY = { name: 'Synthetic Fixture', email: 'synthetic-fixture@example.invalid' };

const CI_DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const REPLAN_SCHEMA = 'sigra.phase253.registration-replan-evidence/v1';
const REPLAN_FREEZE_SCHEMA = 'sigra.phase253.registration-replan-freeze/v1';

const SOURCE_FILES = [
  'scripts/ci/ci-registration-repro.sh',
  'scripts/ci/ci-registration-recovery.mjs',
  'scripts/ci/ci-registration-recovery.test.mjs',
  'scripts/ci/ci-playwright-report.mjs',
  'test/example/priv/playwright/playwright.config.ts',
  'test/example/priv/playwright/tests/admin-eval.spec.ts',
  'test/example/priv/playwright/helpers/adminFlows.ts',
  'test/example/priv/playwright/package-lock.json',
  'test/example/mix.lock',
  '.github/workflows/ci.yml'
];
// The two real, executed entrypoints are copied byte-for-byte; every other bound source is a
// small synthetic placeholder so the fixture needs no lockfile, workflow or Playwright tree.
const COPIED_SOURCES = {
  'scripts/ci/ci-registration-repro.sh': path.join(CI_DIR, 'ci-registration-repro.sh'),
  'scripts/ci/ci-registration-recovery.mjs': path.join(CI_DIR, 'ci-registration-recovery.mjs')
};
// Programs a native run would call. The recording stubs reject and log any invocation.
const STUBBED_PROGRAMS = ['mix', 'npm', 'npx', 'playwright', 'psql', 'createdb', 'dropdb', 'pg_isready', 'curl', 'wget', 'docker', 'chromium'];

const sha256 = (data) => crypto.createHash('sha256').update(data).digest('hex');
const fileSha256 = (file) => sha256(fs.readFileSync(file));
const writeJson = (file, value) => {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, `${JSON.stringify(value, null, 2)}\n`);
};
const readJson = (file) => JSON.parse(fs.readFileSync(file, 'utf8'));
// Must match revisionFreezeDigest() in ci-registration-recovery.mjs: the digest of the freeze
// without its own freeze_sha256 key, in on-disk key order.
const internalFreezeDigest = (freeze) => sha256(JSON.stringify(Object.fromEntries(Object.entries(freeze).filter(([key]) => key !== 'freeze_sha256'))));

function gitEnv() {
  return {
    ...process.env,
    GIT_CONFIG_NOSYSTEM: '1', GIT_CONFIG_GLOBAL: os.devNull,
    GIT_AUTHOR_NAME: FIXTURE_IDENTITY.name, GIT_AUTHOR_EMAIL: FIXTURE_IDENTITY.email,
    GIT_COMMITTER_NAME: FIXTURE_IDENTITY.name, GIT_COMMITTER_EMAIL: FIXTURE_IDENTITY.email
  };
}

function git(root, args) {
  const result = spawnSync('git', ['-C', root, '-c', 'commit.gpgsign=false', '-c', 'core.hooksPath=/dev/null', ...args], { encoding: 'utf8', env: gitEnv() });
  if (result.status !== 0) throw new Error(`fixture git ${args.join(' ')} failed: ${result.stderr}`);
  return result.stdout.trim();
}

function sourceContents(file) {
  const real = COPIED_SOURCES[file];
  if (real) return fs.readFileSync(real);
  return Buffer.from(`// ${SYNTHETIC_LABEL} placeholder for ${file}\n`);
}

function nativeReport(project, title, { duration = 4321 } = {}) {
  return {
    config: { projects: FIXTURE_PROJECTS.map((name) => ({ name })) },
    suites: [{
      title: 'admin-eval.spec.ts', file: 'admin-eval.spec.ts', specs: [],
      suites: [{
        title: 'Admin eval (synthetic)', file: 'admin-eval.spec.ts',
        specs: [{
          title, ok: true, file: 'admin-eval.spec.ts',
          tests: [{
            annotations: [], expectedStatus: 'passed', projectId: project, projectName: project, status: 'expected',
            results: [{ status: 'passed', duration, errors: [], retry: 0, attachments: [], annotations: [] }]
          }]
        }]
      }]
    }],
    errors: [],
    stats: { expected: 1, skipped: 0, unexpected: 0, flaky: 0 }
  };
}

/**
 * Build a complete synthetic committed tree plus a verifiable native-revision receipt.
 *
 * The returned object exposes small mutation helpers that keep every OTHER digest
 * internally consistent, so a test can corrupt exactly one predicate at a time.
 */
export function createRegistrationNativeTreeFixture(options = {}) {
  const label = options.label ?? 'tree';
  const base = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), `sigra-253-native-tree-${label}-`)));
  const root = path.join(base, 'candidate');
  fs.mkdirSync(root);
  git(root, ['init', '-q', '-b', 'main']);

  // Commit 1: the sources the verifier binds to.
  for (const file of SOURCE_FILES) {
    const target = path.join(root, file);
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, sourceContents(file));
  }
  fs.chmodSync(path.join(root, 'scripts/ci/ci-registration-repro.sh'), 0o755);
  git(root, ['add', '--all']);
  git(root, ['commit', '-q', '-m', 'synthetic fixture sources']);
  const sourceHead = git(root, ['rev-parse', 'HEAD']);
  const blobs = Object.fromEntries(SOURCE_FILES.map((file) => [file, git(root, ['rev-parse', `${sourceHead}:${file}`])]));

  // Synthetic historical records (stand-ins for the spent original records).
  const phaseDir = path.join(root, FIXTURE_PHASE_DIR);
  const history = {};
  for (const [key, name] of [
    ['original_freeze', '253-RECOVERY-REGISTRATION-FREEZE.json'],
    ['original_evidence', '253-RECOVERY-REGISTRATION-EVIDENCE.json'],
    ['terminal_diagnostic', '253-09-TERMINAL-DIAGNOSTIC.json'],
    ['recovery_capture', '253-ADDITIONAL-EXECUTION-CAPTURE.json']
  ]) {
    const file = path.join(phaseDir, name);
    writeJson(file, { synthetic_native_fixture: SYNTHETIC_LABEL, record: key, status: 'halted' });
    history[key] = { path: path.relative(root, file), sha256: fileSha256(file) };
  }

  const freezePath = path.join(phaseDir, '253-38-SYNTHETIC-REGISTRATION-FREEZE.json');
  const evidencePath = path.join(phaseDir, '253-38-SYNTHETIC-REGISTRATION-EVIDENCE.json');
  const rawDir = `${evidencePath}.raw`;
  const provenance = { synthetic_native_fixture: SYNTHETIC_LABEL, accepted_as_native_proof: false };

  const slots = [
    ['R-DIAG-DESKTOP', 1, 'admin-eval', 15_000],
    ['R-DIAG-MOBILE', 2, 'admin-eval-mobile', 12_000]
  ].map(([id, sequence, project]) => ({
    id, owner_plan: 15, sequence, kind: 'diagnostic', stage: 'D19', project, max_duration_ms: 120_000, title: SELECTED_TITLE,
    argv: [`--project=${project}`, `--grep=${SELECTED_TITLE}`, '--workers=1', '--retries=0', '--trace=retain-on-failure'],
    selection: { spec: 'tests/admin-eval.spec.ts', title: SELECTED_TITLE, cases: null }
  }));

  const historicalCharge = 3_000;
  const preparationCharge = 2_000;
  const freeze = {
    schema_version: REPLAN_FREEZE_SCHEMA, status: 'frozen_before_results', frozen_at: '2026-01-01T00:00:00.000Z',
    source: { repository: 'synthetic/native-fixture', checkout_head: sourceHead, tracked_worktree_clean_except_exact_preserved_config: false, blobs },
    historical: {
      original_freeze_path: history.original_freeze.path, original_freeze_sha256: history.original_freeze.sha256,
      original_evidence_path: history.original_evidence.path, original_evidence_sha256: history.original_evidence.sha256,
      terminal_diagnostic_path: history.terminal_diagnostic.path, terminal_diagnostic_sha256: history.terminal_diagnostic.sha256,
      recovery_capture_path: history.recovery_capture.path, recovery_capture_sha256: history.recovery_capture.sha256,
      spent_slot_id: 'D19-DIAG-01', spent_browser_launches: 0, spent_charged_ms: historicalCharge,
      preceding_order: 'unknown'
    },
    preparation: { id: 'D19-COMMON-PREPARATION', max_duration_ms: 116_232, charged_duration_ms: preparationCharge },
    ledger: {
      historical_charge_ms: historicalCharge,
      spent_reservations: [{ id: 'D19-DIAG-01', browser_launches: 0, charged_ms: historicalCharge, outcome: 'synthetic_halted' }],
      slots,
      d19: { regular_command_reservations: 8, each_max_duration_ms: 120_000, max_charged_duration_ms: 1_080_000 },
      shared_retry_count: 1, max_new_browser_launches: 18,
      max_charged_duration_ms: 3_480_000, max_total_charged_ms_including_historical: 3_480_000
    },
    provenance
  };

  const attempts = slots.map((slot, index) => {
    const duration = [15_000, 12_000][index];
    const started = 1_000_000_000_000n + BigInt(index) * 100_000_000_000n;
    const attemptDir = path.join(rawDir, slot.id, 'attempt-01');
    fs.mkdirSync(attemptDir, { recursive: true });
    const reference = (name, contents) => {
      const file = path.join(attemptDir, name);
      fs.writeFileSync(file, contents);
      return { path: path.relative(rawDir, file), sha256: fileSha256(file), bytes: fs.statSync(file).size };
    };
    const files = {
      playwright_report: reference('playwright-report.json', JSON.stringify(nativeReport(slot.project, SELECTED_TITLE))),
      traces: [],
      setup_log: reference('setup-log.log', `${SYNTHETIC_LABEL}: database setup complete for ${slot.project}\n`),
      app_log: reference('app-log.log', `${SYNTHETIC_LABEL}: app listening for ${slot.project}\n`),
      test_log: reference('test-log.log', `${SYNTHETIC_LABEL}: 1 passed (${slot.project})\n`),
      drop_log: reference('drop-log.log', `${SYNTHETIC_LABEL}: database dropped\n`)
    };
    return {
      slot_id: slot.id, sequence: slot.sequence, stage: 'D19', project: slot.project, argv: structuredClone(slot.argv),
      source_commit: sourceHead, source_blobs: structuredClone(blobs),
      started_monotonic_ns: started.toString(), ended_monotonic_ns: (started + BigInt(duration) * 1_000_000n).toString(),
      execution_duration_ms: duration, charged_duration_ms: duration,
      database: { name: `sigra_253_recovery_${slot.project.replaceAll('-', '_')}_synthetic_${index + 1}`, setup_exit_code: 0, drop_exit_code: 0 },
      server: { port: 25311 + index, http_status: 200, app_pid: 4242 + index },
      browser: { launched: true, exit_code: 0 },
      observed_outcome: 'passed',
      registration: { server_post_confirmed: true, success_flash_asserted: true },
      files,
      toolchain: { node: 'v20.18.1', playwright: '1.59.1', mix: 'synthetic', ecto_sql: '3.13.5', phoenix_live_view: '1.1.28' },
      build_directory_removed: true, build_path: '/synthetic/fixture/mix-build', terminal_diagnostic: null
    };
  });

  const attemptCharge = attempts.reduce((sum, item) => sum + item.charged_duration_ms, 0);
  const evidence = {
    schema_version: REPLAN_SCHEMA, status: 'diagnosis_incomplete',
    freeze_path: path.relative(root, freezePath), freeze_sha256: null,
    source: { checkout_head: sourceHead, blobs: structuredClone(blobs) },
    historical: { ...structuredClone(freeze.historical), preceding_order: 'unknown' },
    preparation_status: 'passed',
    preparation_receipts: [{ label: 'synthetic-preparation', duration_ms: preparationCharge, exit_code: 0 }],
    attempts,
    limits: {
      historical_charge_ms: historicalCharge, preparation_charge_ms: preparationCharge,
      charged_duration_ms: historicalCharge + preparationCharge + attemptCharge,
      browser_launches: attempts.length, used_slots: attempts.map((item) => item.slot_id),
      max_charged_duration_ms: freeze.ledger.max_charged_duration_ms, max_new_browser_launches: freeze.ledger.max_new_browser_launches
    },
    provenance
  };

  const stubBin = path.join(base, 'stub-bin');
  const stubRecord = path.join(base, 'stub-calls.log');
  fs.mkdirSync(stubBin);
  fs.writeFileSync(stubRecord, '');
  for (const program of STUBBED_PROGRAMS) {
    const file = path.join(stubBin, program);
    fs.writeFileSync(file, `#!/bin/sh\nprintf '%s\\n' "${program} $*" >> '${stubRecord}'\nexit 97\n`);
    fs.chmodSync(file, 0o755);
  }

  const fixture = {
    base, root, phaseDir, freezePath, evidencePath, rawDir, sourceHead, blobs, history,
    runner: path.join(root, 'scripts/ci/ci-registration-repro.sh'),
    recoveryModule: path.join(root, 'scripts/ci/ci-registration-recovery.mjs'),
    stubBin, stubRecord,
    readFreeze: () => readJson(freezePath),
    readEvidence: () => readJson(evidencePath),
    attemptFor: (slotId) => readJson(evidencePath).attempts.find((item) => item.slot_id === slotId),
    reportPath(slotId) {
      const attempt = readJson(evidencePath).attempts.find((item) => item.slot_id === slotId);
      return path.join(rawDir, attempt.files.playwright_report.path);
    },
    /** Rewrite the freeze; keeps its internal digest valid and rebinds the evidence to the new file bytes. */
    rewriteFreeze(mutate, { rebind = true, internalDigest = true } = {}) {
      const next = readJson(freezePath);
      mutate(next);
      if (internalDigest) {
        delete next.freeze_sha256;
        next.freeze_sha256 = internalFreezeDigest(next);
      }
      writeJson(freezePath, next);
      if (rebind) fixture.rewriteEvidence((item) => { item.freeze_sha256 = fileSha256(freezePath); });
      return next;
    },
    rewriteEvidence(mutate) {
      const next = readJson(evidencePath);
      mutate(next);
      writeJson(evidencePath, next);
      return next;
    },
    /** Rewrite a native report and (by default) keep the retained-file digest consistent with it. */
    rewriteReport(slotId, mutate, { updateDigest = true } = {}) {
      const evidence = readJson(evidencePath);
      const attempt = evidence.attempts.find((item) => item.slot_id === slotId);
      const file = path.join(rawDir, attempt.files.playwright_report.path);
      const report = readJson(file);
      mutate(report, attempt);
      fs.writeFileSync(file, JSON.stringify(report));
      if (updateDigest) {
        attempt.files.playwright_report.sha256 = fileSha256(file);
        attempt.files.playwright_report.bytes = fs.statSync(file).size;
        writeJson(evidencePath, evidence);
      }
    },
    appendRaw(slotId, name, text) {
      const attempt = readJson(evidencePath).attempts.find((item) => item.slot_id === slotId);
      fs.appendFileSync(path.join(rawDir, attempt.files[name].path), text);
    },
    env: () => ({ ...process.env, PATH: `${stubBin}${path.delimiter}${process.env.PATH}`, GIT_CONFIG_NOSYSTEM: '1', GIT_CONFIG_GLOBAL: os.devNull }),
    /** Invoke the copied shell entrypoint from the temporary committed root. */
    run(args, extra = {}) {
      return spawnSync(fixture.runner, args, { cwd: root, encoding: 'utf8', env: fixture.env(), ...extra });
    },
    verify(extra) { return fixture.run(['--verify-diagnostic', evidencePath, '--revision'], extra); },
    verifySavedNative(extra) { return fixture.run(['--verify-saved-native', evidencePath], extra); },
    /** Recorded native setup/browser/database invocations (must stay empty). */
    stubCalls: () => fs.readFileSync(stubRecord, 'utf8').split('\n').filter(Boolean),
    git: (args) => git(root, args),
    commitAll(message = 'synthetic fixture records') {
      git(root, ['add', '--all']);
      git(root, ['commit', '-q', '-m', message]);
      return git(root, ['rev-parse', 'HEAD']);
    },
    cleanup() { fs.rmSync(base, { recursive: true, force: true }); }
  };

  writeJson(freezePath, (() => { freeze.freeze_sha256 = internalFreezeDigest(freeze); return freeze; })());
  evidence.freeze_sha256 = fileSha256(freezePath);
  writeJson(evidencePath, evidence);
  fixture.headWithRecords = fixture.commitAll('synthetic fixture freeze and receipts');
  return fixture;
}

export function fixtureFileSha256(file) { return fileSha256(file); }

#!/usr/bin/env node

import { spawnSync } from 'node:child_process';
import { copyFile, mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';

const SHA_RE = /^[0-9a-f]{40}$/;

function fail(message) {
  console.error(`measure-playwright-drift: FAIL: ${message}`);
  process.exitCode = 1;
}

function argValue(args, name) {
  const index = args.indexOf(name);
  return index < 0 ? undefined : args[index + 1];
}

function run(command, args, options = {}) {
  const result = spawnSync(command, args, {
    encoding: 'utf8',
    maxBuffer: 16 * 1024 * 1024,
    ...options,
  });
  if (result.error) throw result.error;
  return result;
}

function assertSafeInventoryPath(value) {
  if (typeof value !== 'string' || value.length === 0 || value.includes('\\')) {
    throw new Error('inventory path must be a non-empty repository-relative POSIX path');
  }
  if (path.posix.isAbsolute(value) || value.split('/').some((part) => part === '..' || part === '.')) {
    throw new Error(`unsafe inventory path: ${value}`);
  }
  if (!/^test\/example\/priv\/playwright\/tests\/[^/]+-snapshots\/[^/]+\.png$/.test(value)) {
    throw new Error(`path is outside the committed Playwright snapshot inventory: ${value}`);
  }
  return value;
}

function gitInventory(sourceSha) {
  if (!SHA_RE.test(sourceSha ?? '')) throw new Error('source SHA must be 40 lowercase hexadecimal characters');
  const result = run('git', ['ls-tree', '-r', '--name-only', sourceSha, '--', 'test/example/priv/playwright/tests']);
  if (result.status !== 0) throw new Error(`git ls-tree failed: ${result.stderr.trim()}`);
  return result.stdout.split(/\r?\n/).filter((entry) => entry && /^test\/example\/priv\/playwright\/tests\/[^/]+-snapshots\/[^/]+\.png$/.test(entry)).map(assertSafeInventoryPath).sort();
}

function samePaths(expected, actual) {
  const left = [...expected].sort();
  const right = [...actual].map(assertSafeInventoryPath).sort();
  return left.length === right.length && left.every((value, index) => value === right[index]);
}

function requireRunIdentity(manifest, sourceSha) {
  if (!manifest || typeof manifest !== 'object' || Array.isArray(manifest)) {
    throw new Error('manifest must be a JSON object');
  }
  if (manifest.source_sha !== sourceSha) throw new Error('manifest source_sha does not match the requested source SHA');
  if (!SHA_RE.test(manifest.source_sha ?? '')) throw new Error('manifest source_sha is malformed');
  if (!/^\d+$/.test(String(manifest.run_id ?? ''))) throw new Error('manifest run_id is missing or malformed');
  if (typeof manifest.workflow_name !== 'string' || manifest.workflow_name !== 'Phase 244 Playwright measurement') {
    throw new Error('manifest workflow_name does not identify the Phase 244 measurement workflow');
  }
  if (manifest.event !== 'workflow_dispatch' || typeof manifest.head_branch !== 'string' || !manifest.head_branch.startsWith('phase-244/')) {
    throw new Error('manifest is not bound to an authorized phase-244 workflow_dispatch branch');
  }
  if (manifest.package_versions?.render_a !== '1.59.1' || manifest.package_versions?.render_b !== '1.59.1') {
    throw new Error('manifest package versions must both identify the locked 1.59.1 baseline');
  }
  if (!/^\d+$/.test(String(manifest.chromium_revisions?.render_a ?? '')) ||
      !/^\d+$/.test(String(manifest.chromium_revisions?.render_b ?? ''))) {
    throw new Error('manifest Chromium revisions are missing or malformed');
  }
  if (typeof manifest.comparator?.name !== 'string' || typeof manifest.comparator?.version !== 'string' ||
      !manifest.comparator.version.includes('ImageMagick')) {
    throw new Error('manifest comparator identity is missing or malformed');
  }
}

async function verifyManifest(args) {
  const file = argValue(args, '--manifest');
  const sourceSha = argValue(args, '--source-sha');
  if (!file || !sourceSha) throw new Error('verify requires --manifest and --source-sha');
  const manifest = JSON.parse(await readFile(file, 'utf8'));
  requireRunIdentity(manifest, sourceSha);
  if (manifest.verdict !== 'zero-drift') throw new Error(`manifest verdict is ${manifest.verdict ?? 'missing'}`);
  const expected = gitInventory(sourceSha);
  const expectCountArg = argValue(args, '--expect-count');
  const expectCount = expectCountArg === undefined && args.includes('--inventory-only')
    ? expected.length
    : Number(expectCountArg);
  if (!Number.isInteger(expectCount) || expectCount < 1) throw new Error('--expect-count must be a positive integer');
  if (!Array.isArray(manifest.results) || manifest.results.length !== expectCount) {
    throw new Error(`manifest must contain exactly ${expectCount} result(s)`);
  }
  if (!Array.isArray(manifest.inventory) || !samePaths(manifest.inventory, manifest.results.map((entry) => entry.path))) {
    throw new Error('manifest inventory and result paths do not match exactly');
  }
  if (args.includes('--inventory-only') && !samePaths(expected, manifest.inventory)) {
    throw new Error(`manifest path set differs from the ${expected.length}-path inventory at ${sourceSha}`);
  }
  if (!manifest.inventory.every((entry) => expected.includes(assertSafeInventoryPath(entry)))) {
    throw new Error('manifest includes a path outside the tracked inventory at the requested source SHA');
  }
  for (const entry of manifest.results) {
    assertSafeInventoryPath(entry.path);
    if (!Number.isInteger(entry.width) || entry.width <= 0 || !Number.isInteger(entry.height) || entry.height <= 0) {
      throw new Error(`invalid dimensions for ${entry.path}`);
    }
    if (!Number.isInteger(entry.changed_pixels) || entry.changed_pixels !== 0) {
      throw new Error(`comparison is not exact zero drift for ${entry.path}`);
    }
    if (!entry.render_a || !entry.render_b || !entry.diff) throw new Error(`render/diff artifact path missing for ${entry.path}`);
  }
  if (args.includes('--inventory-only') && (
    !samePaths(expected, manifest.rendered_paths?.render_a ?? []) ||
    !samePaths(expected, manifest.rendered_paths?.render_b ?? [])
  )) {
    throw new Error('one or both rendered path sets differ from the complete tracked inventory');
  }
  console.log(JSON.stringify({ valid: true, source_sha: sourceSha, run_id: manifest.run_id, paths: manifest.inventory.length }));
}

function strictAeOutput(stderr) {
  const match = stderr.match(/^\s*(\d+)\s*$/);
  if (!match) throw new Error(`ImageMagick AE output is unavailable or malformed: ${JSON.stringify(stderr.trim())}`);
  const count = Number(match[1]);
  if (!Number.isSafeInteger(count)) throw new Error('ImageMagick AE count is outside the safe integer range');
  return count;
}

function compare(args) {
  const [left, right, diff] = args;
  if (!left || !right || !diff || args.length !== 3) throw new Error('compare requires <render-a.png> <render-b.png> <diff.png>');
  const result = run('compare', ['-metric', 'AE', '-fuzz', '0%', left, right, diff]);
  if (result.status !== 0 && result.status !== 1) {
    throw new Error(`ImageMagick compare failed (exit ${result.status}): ${result.stderr.trim()}`);
  }
  const changedPixels = strictAeOutput(result.stderr);
  console.log(JSON.stringify({ changed_pixels: changedPixels, diff }));
  if (changedPixels !== 0) process.exitCode = 1;
}

async function buildManifest(args) {
  const sourceSha = argValue(args, '--source-sha');
  const runId = argValue(args, '--run-id');
  const branch = argValue(args, '--branch');
  const scope = argValue(args, '--scope');
  const inventoryFile = argValue(args, '--inventory-file');
  const renderA = argValue(args, '--render-a');
  const renderB = argValue(args, '--render-b');
  const artifactDir = argValue(args, '--artifact-dir');
  const revisionA = argValue(args, '--chromium-revision-a');
  const revisionB = argValue(args, '--chromium-revision-b');
  const packageA = argValue(args, '--package-a');
  const packageB = argValue(args, '--package-b');
  const comparatorVersionFile = argValue(args, '--comparator-version-file');
  const captureStatusA = argValue(args, '--capture-status-a') ?? '0';
  const captureStatusB = argValue(args, '--capture-status-b') ?? '0';
  const output = argValue(args, '--output');
  if (!sourceSha || !runId || !branch || !scope || !inventoryFile || !renderA || !renderB || !artifactDir || !output) {
    throw new Error('build-manifest is missing required arguments');
  }
  if (!SHA_RE.test(sourceSha) || !/^\d+$/.test(runId) || !branch.startsWith('phase-244/')) {
    throw new Error('build-manifest has invalid run identity');
  }
  if (!['tracer', 'full'].includes(scope)) throw new Error('scope must be tracer or full');
  const fullInventory = gitInventory(sourceSha);
  const suppliedInventory = JSON.parse(await readFile(inventoryFile, 'utf8'));
  if (suppliedInventory.source_sha !== sourceSha || !samePaths(fullInventory, suppliedInventory.paths ?? [])) {
    throw new Error('inventory input does not match git ls-tree at the requested source SHA');
  }
  const selected = scope === 'tracer'
    ? fullInventory.filter((entry) => entry.endsWith('-admin-checkpoints-chromium.png')).slice(0, 1)
    : fullInventory;
  if (selected.length === 0) throw new Error('the measured source SHA has no eligible tracked PNGs');

  const diagnostics = [];
  const missingPaths = new Set();
  for (const relativePath of selected) {
    const sourceA = path.join(renderA, relativePath);
    const sourceB = path.join(renderB, relativePath);
    const aStat = run('test', ['-f', sourceA]);
    const bStat = run('test', ['-f', sourceB]);
    if (aStat.status !== 0 || bStat.status !== 0) {
      diagnostics.push(`required screenshot was not rendered in both roots: ${relativePath}`);
      missingPaths.add(relativePath);
    }
  }
  let actualA = [];
  let actualB = [];
  if (scope === 'full') {
    actualA = await listPngs(renderA);
    actualB = await listPngs(renderB);
    if (!samePaths(fullInventory, actualA)) diagnostics.push('render-a path set differs from the tracked PNG inventory');
    if (!samePaths(fullInventory, actualB)) diagnostics.push('render-b path set differs from the tracked PNG inventory');
  }

  await mkdir(path.join(artifactDir, 'render-a'), { recursive: true });
  await mkdir(path.join(artifactDir, 'render-b'), { recursive: true });
  await mkdir(path.join(artifactDir, 'diffs'), { recursive: true });
  const results = [];
  for (const relativePath of selected) {
    if (missingPaths.has(relativePath)) continue;
    const renderAFile = path.posix.join('render-a', relativePath);
    const renderBFile = path.posix.join('render-b', relativePath);
    const diffFile = path.posix.join('diffs', relativePath.replace(/\.png$/, '.diff.png'));
    const absoluteA = path.join(artifactDir, renderAFile);
    const absoluteB = path.join(artifactDir, renderBFile);
    const absoluteDiff = path.join(artifactDir, diffFile);
    await mkdir(path.dirname(absoluteA), { recursive: true });
    await mkdir(path.dirname(absoluteB), { recursive: true });
    await mkdir(path.dirname(absoluteDiff), { recursive: true });
    try {
      await copyFile(path.join(renderA, relativePath), absoluteA);
      await copyFile(path.join(renderB, relativePath), absoluteB);
    } catch (error) {
      diagnostics.push(`could not copy render artifact for ${relativePath}: ${error.message}`);
      continue;
    }
    const dimensionsA = run('identify', ['-format', '%w %h', absoluteA]);
    const dimensionsB = run('identify', ['-format', '%w %h', absoluteB]);
    if (dimensionsA.status !== 0 || dimensionsB.status !== 0) {
      diagnostics.push(`could not read PNG dimensions for ${relativePath}`);
      continue;
    }
    if (dimensionsA.stdout !== dimensionsB.stdout) {
      diagnostics.push(`render dimensions differ for ${relativePath}`);
      continue;
    }
    const [width, height] = dimensionsA.stdout.trim().split(/\s+/).map(Number);
    const compareResult = run('compare', ['-metric', 'AE', '-fuzz', '0%', absoluteA, absoluteB, absoluteDiff]);
    if (compareResult.status !== 0 && compareResult.status !== 1) {
      diagnostics.push(`ImageMagick compare failed for ${relativePath}: ${compareResult.stderr.trim()}`);
      continue;
    }
    let changedPixels;
    try {
      changedPixels = strictAeOutput(compareResult.stderr);
    } catch (error) {
      diagnostics.push(`${relativePath}: ${error.message}`);
      continue;
    }
    results.push({ path: relativePath, width, height, changed_pixels: changedPixels, render_a: renderAFile, render_b: renderBFile, diff: diffFile });
  }
  const comparatorVersion = comparatorVersionFile ? (await readFile(comparatorVersionFile, 'utf8')).trim() : 'unknown';
  const manifest = {
    schema_version: 1,
    workflow_name: 'Phase 244 Playwright measurement',
    event: 'workflow_dispatch',
    head_branch: branch,
    source_sha: sourceSha,
    run_id: runId,
    scope,
    inventory: selected,
    rendered_paths: scope === 'full' ? { render_a: actualA, render_b: actualB } : { render_a: selected, render_b: selected },
    package_versions: { render_a: packageA ?? 'unknown', render_b: packageB ?? 'unknown' },
    chromium_revisions: { render_a: revisionA ?? 'unknown', render_b: revisionB ?? 'unknown' },
    comparator: { name: 'ImageMagick compare -metric AE -fuzz 0%', version: comparatorVersion },
    results,
    diagnostics: [
      ...(captureStatusA === '0' ? [] : [`render-a capture exited ${captureStatusA}`]),
      ...(captureStatusB === '0' ? [] : [`render-b capture exited ${captureStatusB}`]),
      ...diagnostics,
    ],
    verdict: captureStatusA !== '0' || captureStatusB !== '0' || diagnostics.length > 0
      ? 'inconclusive'
      : results.some((entry) => entry.changed_pixels > 0) ? 'drift' : 'zero-drift',
  };
  await writeFile(output, `${JSON.stringify(manifest, null, 2)}\n`, { mode: 0o600 });
  if (manifest.verdict !== 'zero-drift') throw new Error(`measurement verdict is ${manifest.verdict}; see manifest and diff artifacts`);
  console.log(JSON.stringify({ valid: true, source_sha: sourceSha, run_id: runId, paths: results.length, verdict: manifest.verdict }));
}

async function listPngs(root) {
  const snapshotRoot = path.join(root, 'test/example/priv/playwright/tests');
  const result = run('find', [snapshotRoot, '-type', 'f', '-path', '*-snapshots/*.png', '-print']);
  if (result.status !== 0) throw new Error(`could not list rendered PNGs under ${root}`);
  return result.stdout.split(/\r?\n/).filter(Boolean).map((file) => path.relative(root, file).split(path.sep).join('/')).map(assertSafeInventoryPath).sort();
}

async function main() {
  const [, , command, ...args] = process.argv;
  if (command === 'verify') return await verifyManifest(args);
  if (command === 'compare') return compare(args);
  if (command === 'build-manifest') return await buildManifest(args);
  if (command === 'inventory') {
    const sourceSha = argValue(args, '--source-sha');
    if (!sourceSha) throw new Error('inventory requires --source-sha');
    console.log(JSON.stringify({ source_sha: sourceSha, paths: gitInventory(sourceSha) }, null, 2));
    return;
  }
  throw new Error('usage: measure-playwright-drift.mjs inventory|compare|verify ...');
}

main().catch((error) => fail(error.message));

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const SCRIPT = path.join(ROOT, 'scripts/ci/measure-playwright-drift.mjs');
const CI = await readFile(path.join(ROOT, '.github/workflows/ci.yml'), 'utf8');
const MEASURE_WORKFLOW = await readFile(path.join(ROOT, '.github/workflows/phase-244-playwright-measure.yml'), 'utf8');
const SOURCE_SHA = spawnSync('git', ['rev-parse', 'HEAD'], { cwd: ROOT, encoding: 'utf8' }).stdout.trim();

function command(args) {
  return spawnSync(process.execPath, [SCRIPT, ...args], { cwd: ROOT, encoding: 'utf8' });
}

function trackedInventory() {
  const result = command(['inventory', '--source-sha', SOURCE_SHA]);
  assert.equal(result.status, 0, result.stderr);
  return JSON.parse(result.stdout);
}

function validManifest(inventory) {
  return {
    schema_version: 1,
    workflow_name: 'Phase 244 Playwright measurement',
    event: 'workflow_dispatch',
    head_branch: 'phase-244/measure-test',
    source_sha: SOURCE_SHA,
    run_id: '1234567890',
    scope: 'full',
    inventory: inventory.paths,
    rendered_paths: { render_a: inventory.paths, render_b: inventory.paths },
    package_versions: { render_a: '1.59.1', render_b: '1.59.1' },
    chromium_revisions: { render_a: '1217', render_b: '1217' },
    comparator: { name: 'ImageMagick compare -metric AE -fuzz 0%', version: 'ImageMagick 6.9.12' },
    results: inventory.paths.map((snapshot) => ({
      path: snapshot,
      width: 1280,
      height: 720,
      changed_pixels: 0,
      render_a: `render-a/${snapshot}`,
      render_b: `render-b/${snapshot}`,
      diff: `diffs/${snapshot.replace(/\.png$/, '.diff.png')}`,
    })),
    diagnostics: [],
    verdict: 'zero-drift',
  };
}

async function verifyWith(manifest, flags = ['--inventory-only']) {
  const directory = await mkdtemp(path.join(os.tmpdir(), 'phase-244-manifest-'));
  const file = path.join(directory, 'manifest.json');
  try {
    await writeFile(file, JSON.stringify(manifest));
    return command(['verify', '--manifest', file, '--source-sha', SOURCE_SHA, ...flags]);
  } finally {
    await rm(directory, { recursive: true, force: true });
  }
}

function extractFinalMainGuard() {
  const step = CI.match(/      - name: Require release tag ref for manual release evidence([\s\S]*?)(?=      - name:)/)?.[1];
  assert.ok(step, 'release-ref guard step must exist');
  const script = step.match(/        run: \|\n((?:          .*\n)+)/)?.[1];
  assert.ok(script, 'release-ref guard must have an executable run block');
  return script.split('\n').map((line) => line.replace(/^ {10}/, '')).join('\n');
}

function runFinalMainGuard({ event = 'workflow_dispatch', enabled = 'true', ref = 'refs/heads/main', recapture = '', failProbe = 'false', rotProbe = 'false' } = {}) {
  return spawnSync('bash', ['-euo', 'pipefail', '-c', extractFinalMainGuard()], {
    cwd: ROOT,
    encoding: 'utf8',
    env: {
      ...process.env,
      EVENT_NAME: event,
      PHASE_244_FINAL_MAIN: enabled,
      REF: ref,
      GITHUB_REF: ref,
      RECAPTURE_BRANCH: recapture,
      FORCE_FAIL_PROBE: failProbe,
      FORCE_ROT_PROBE: rotProbe,
    },
  });
}

test('inventory is derived from the source commit and contains the complete tracked PNG set', () => {
  const inventory = trackedInventory();
  assert.equal(inventory.source_sha, SOURCE_SHA);
  assert.equal(inventory.paths.length, 115);
  assert.ok(inventory.paths.every((entry) => /^test\/example\/priv\/playwright\/tests\/[^/]+-snapshots\/[^/]+\.png$/.test(entry)));
  assert.deepEqual(inventory.paths, [...inventory.paths].sort());
});

test('a complete same-source Ubuntu receipt verifies', async () => {
  const inventory = trackedInventory();
  const result = await verifyWith(validManifest(inventory));
  assert.equal(result.status, 0, result.stderr);
  assert.match(result.stdout, /"valid":true/);
});

test('an incomplete capture path set fails closed', async () => {
  const inventory = trackedInventory();
  const manifest = validManifest(inventory);
  manifest.inventory.pop();
  manifest.rendered_paths.render_a.pop();
  manifest.results.pop();
  const result = await verifyWith(manifest);
  assert.notEqual(result.status, 0);
  assert.match(result.stderr, /result\(s\)|path set differs/);
});

test('an extra or traversal path cannot enter the inventory', async () => {
  const inventory = trackedInventory();
  const manifest = validManifest(inventory);
  manifest.inventory[0] = '../outside.png';
  manifest.rendered_paths.render_a[0] = '../outside.png';
  manifest.rendered_paths.render_b[0] = '../outside.png';
  manifest.results[0] = { path: '../outside.png', width: 1, height: 1, changed_pixels: 0, render_a: 'a', render_b: 'b', diff: 'c' };
  const result = await verifyWith(manifest);
  assert.notEqual(result.status, 0);
  assert.match(result.stderr, /unsafe inventory path/);
});

test('any changed pixel prevents a zero-drift verdict', async () => {
  const inventory = trackedInventory();
  const manifest = validManifest(inventory);
  manifest.results[0].changed_pixels = 1;
  const result = await verifyWith(manifest);
  assert.notEqual(result.status, 0);
  assert.match(result.stderr, /not exact zero drift/);
});

test('the final-main route admits only the exact safe dispatch inputs', () => {
  assert.equal(runFinalMainGuard().status, 0);
  assert.notEqual(runFinalMainGuard({ ref: 'refs/heads/phase-244/measure' }).status, 0);
  assert.notEqual(runFinalMainGuard({ ref: 'refs/tags/v1.0.0' }).status, 0);
  assert.notEqual(runFinalMainGuard({ enabled: 'false' }).status, 0);
  assert.notEqual(runFinalMainGuard({ recapture: 'candidate-branch' }).status, 0);
  assert.notEqual(runFinalMainGuard({ failProbe: 'true' }).status, 0);
  assert.notEqual(runFinalMainGuard({ rotProbe: 'true' }).status, 0);
  assert.equal(runFinalMainGuard({ enabled: 'false', recapture: 'candidate-branch' }).status, 0);
});

test('measurement workflow is read-only and gated to explicit phase-244 branch dispatches', () => {
  assert.match(MEASURE_WORKFLOW, /contents:\s*read/);
  assert.match(MEASURE_WORKFLOW, /inputs\.phase_244_measure == true/);
  assert.match(MEASURE_WORKFLOW, /github\.ref_type == 'branch'/);
  assert.match(MEASURE_WORKFLOW, /startsWith\(github\.ref, 'refs\/heads\/phase-244\/'\)/);
  assert.doesNotMatch(MEASURE_WORKFLOW, /contents:\s*write/);
});

