// P12 (230-09-PLAN.md, 236-05-PLAN.md) — mechanical, offline provenance enforcement.
//
// A captured observation must retain its verbatim run ID, the command that produced it, and
// corroboration inside the same slot. `readSubject()` keeps a single injected-subject seam for
// committed fail-first fixtures while transparently finding archived default ledgers.

import test from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readSubject, readRepoFile, parseEvidenceSlots } from './_lib.mjs';

const PHASE_230_LEDGER =
  '.planning/phases/230-tier-1-critical-path-reclamation/230-EVIDENCE.md';
const PHASE_236_LEDGER =
  'test/fixtures/prohibitions/retained-236-evidence.md';

// Product-only publication retains the server parent's old live planning ledger.
// Read the exact corrected source copy explicitly, rather than selecting whichever
// live/archive directory happens to exist in the checkout. Injection still uses
// readSubject below so the original known-bad controls remain effective.
test('the retained source ledger matches its recorded bytes', () => {
  const origin = JSON.parse(readRepoFile('test/fixtures/prohibitions/retained-236-evidence.json'));
  assert.equal(origin.source_commit, '16800f4319cdd0e2554938071d4ebc48caa969ac');
  assert.equal(origin.source_path, '.planning/milestones/v1.48-phases/236-flake-root-cause-reproduce-name-fix/236-EVIDENCE.md');
  assert.equal(createHash('sha256').update(readRepoFile(PHASE_236_LEDGER)).digest('hex'), origin.sha256);
});

const DEFAULT_LEDGER_SPECS = Object.freeze([
  {
    label: 'Phase 230 evidence ledger',
    path: PHASE_230_LEDGER,
    minSlots: 4,
    minCaptured: 3,
  },
  {
    label: 'Phase 236 evidence ledger',
    path: PHASE_236_LEDGER,
    minSlots: 3,
    minCaptured: 3,
  },
]);

const ledgerSpecs = process.env.GSD_PROHIB_SUBJECT
  ? [
      {
        label: `injected evidence subject ${process.env.GSD_PROHIB_SUBJECT}`,
        path: PHASE_236_LEDGER,
        minSlots: 3,
        minCaptured: 3,
      },
    ]
  : DEFAULT_LEDGER_SPECS;

const ledgers = ledgerSpecs.map((spec) => ({
  ...spec,
  slots: parseEvidenceSlots(readSubject(spec.path)),
}));

for (const ledger of ledgers) {
  test(`${ledger.label}: the parse finds a non-trivial set of observation slots`, () => {
    assert.ok(
      ledger.slots.length >= ledger.minSlots,
      `${ledger.label} parsed only ${ledger.slots.length} BEFORE-*/AFTER-* slot(s), below its ` +
        `${ledger.minSlots}-slot floor — the parse broke, this is not a pass.`,
    );
  });

  test(`${ledger.label}: every slot declares a Status in the allowed grammar`, () => {
    for (const slot of ledger.slots) {
      assert.ok(
        slot.statusRaw,
        `${ledger.label} slot ${slot.name} has no \`Status:\` line. A slot with no status is ` +
          'neither captured nor honestly booked as pending — it is silence, which reads as evidence.',
      );
      assert.match(
        slot.statusRaw,
        /^(captured \((run|runs) [\s\S]+\)|pending \(.+\))$/,
        `${ledger.label} slot ${slot.name} has Status "${slot.statusRaw}", which is neither ` +
          '\`captured (run <id>)\` nor \`pending (<reason>)\`.',
      );
    }
  });

  test(`${ledger.label}: every captured slot names at least one Status run ID`, () => {
    const captured = ledger.slots.filter((slot) => slot.captured);
    assert.ok(
      captured.length >= ledger.minCaptured,
      `${ledger.label} has only ${captured.length} captured slot(s), below its ` +
        `${ledger.minCaptured}-captured-slot floor — the parse broke, this is not a pass.`,
    );
    for (const slot of captured) {
      assert.ok(
        slot.statusRunIds.length >= 1,
        `${ledger.label} slot ${slot.name} cites no run ID in its Status line ` +
          `("${slot.statusRaw}"). A claim without a run ID is not evidence.`,
      );
    }
  });

  test(`${ledger.label}: every captured slot records a producing command`, () => {
    for (const slot of ledger.slots.filter((candidate) => candidate.captured)) {
      assert.ok(
        slot.fenced.length >= 1,
        `${ledger.label} slot ${slot.name} has no fenced block. The command that produced the ` +
          'numbers must be on the record so a reader can re-derive them.',
      );
      const hasCommand = slot.fenced.some(
        (block) => block.includes('ci-run-metrics.sh') || /\bgh (run|pr|api)\b/.test(block),
      );
      assert.ok(
        hasCommand,
        `${ledger.label} slot ${slot.name} has fenced blocks but none invokes the committed ` +
          'instrument (\`ci-run-metrics.sh\`) or \`gh\`. Output pasted with no producing command ' +
          'is a number nobody can reproduce.',
      );
    }
  });

  test(`${ledger.label}: each captured Status run ID is corroborated in its slot body`, () => {
    for (const slot of ledger.slots.filter((candidate) => candidate.captured)) {
      for (const id of slot.statusRunIds) {
        const occurrences = slot.runIds.filter((runId) => runId === id).length;
        assert.ok(
          occurrences >= 2,
          `${ledger.label} slot ${slot.name} declares run ${id} in its Status but the id appears ` +
            `${occurrences} time(s) in the slot — the Status is not corroborated by the recorded ` +
            'commands or output.',
        );
      }
    }
  });

  test(`${ledger.label}: each pending slot books its obligation instead of claiming a number`, () => {
    for (const slot of ledger.slots.filter((candidate) => candidate.pending)) {
      assert.match(
        slot.statusRaw,
        /pending \(.*obligation.*\)/i,
        `${ledger.label} slot ${slot.name} does not name its obligation ("${slot.statusRaw}"). ` +
          'A pending slot must say WHY it cannot be captured, or it reads as an evidence hole.',
      );
      assert.ok(
        slot.fenced.length >= 1,
        `${ledger.label} slot ${slot.name} records no capture command. A deferred observation ` +
          'without the exact command to run later is a dropped obligation, not a booked one.',
      );
    }
  });
}

// P18 (241-06) — independent monotonic-decrease bookkeeping counters.
// Each counter owns a different surface and vocabulary. Do not fuse them: a
// decrease in one surface cannot pay for an increase in another. Zero is not
// a target; these tests enforce only non-increase against committed baselines.

import { execFileSync } from 'node:child_process';
import test from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';

import {
  BOOKKEEPING_V3_RE,
  docRangeScan,
  P18InstrumentFailure,
} from './_p18-lib.mjs';
import { REPO_ROOT } from './_lib.mjs';

const DEFAULT_BASELINE = 'scripts/ci/prohibitions/p18-ratchet-baseline.tsv';
const EXPECTED_COUNTERS = ['R1', 'R2', 'R3'];

function baselinePath() {
  // Resolve at call time. A module-load read would silently ignore a fixture
  // override in a warm test process and make the independent RED proof false.
  return process.env.GSD_P18_BASELINE || DEFAULT_BASELINE;
}

function loadBaselines() {
  const relPath = baselinePath();
  const path = resolve(REPO_ROOT, relPath);
  if (!existsSync(path)) {
    throw new P18InstrumentFailure(
      `baseline not found at ${path} — a missing baseline is a broken run, never a clean pass`,
    );
  }

  const rows = readFileSync(path, 'utf8')
    .split('\n')
    .map((line) => line.replace(/\r$/, ''))
    .filter((line) => line !== '' && !line.startsWith('#'));
  if (rows.shift() !== 'counter\tbaseline\tsurface') {
    throw new P18InstrumentFailure(`malformed baseline header in ${relPath}`);
  }

  const baselines = new Map();
  for (const row of rows) {
    const [counter, rawBaseline, surface] = row.split('\t');
    if (!counter || !/^(0|[1-9]\d*)$/.test(rawBaseline ?? '') || !surface) {
      throw new P18InstrumentFailure(`malformed baseline row in ${relPath}: ${row}`);
    }
    if (baselines.has(counter)) {
      throw new P18InstrumentFailure(`duplicate baseline counter ${counter} in ${relPath}`);
    }
    baselines.set(counter, Number(rawBaseline));
  }
  if (baselines.size !== EXPECTED_COUNTERS.length || EXPECTED_COUNTERS.some((id) => !baselines.has(id))) {
    throw new P18InstrumentFailure(`baseline must contain exactly ${EXPECTED_COUNTERS.join(', ')} in ${relPath}`);
  }
  return baselines;
}

function trackedLibFiles() {
  const stdout = execFileSync('git', ['ls-files', 'lib/*.ex', 'lib/*.exs'], {
    cwd: REPO_ROOT,
    encoding: 'utf8',
  });
  const files = stdout.split('\n').filter(Boolean);
  if (files.length === 0) {
    throw new P18InstrumentFailure('R2 found no tracked lib Elixir files — refusing to report success on no input');
  }
  return files;
}

function r2CommentLineTotal() {
  let commentLines = 0;
  let matchedLines = 0;
  for (const path of trackedLibFiles()) {
    for (const line of readFileSync(resolve(REPO_ROOT, path), 'utf8').split('\n')) {
      if (!/^\s*#/.test(line)) continue;
      commentLines += 1;
      if (BOOKKEEPING_V3_RE.test(line)) matchedLines += 1;
    }
  }
  if (commentLines === 0) {
    throw new P18InstrumentFailure('R2 found zero comment-only lines — this is not a measurable comment surface');
  }
  return matchedLines;
}

function packagedDocsFiles() {
  const stdout = execFileSync('git', ['ls-files', 'docs', 'README.md', 'CHANGELOG.md'], {
    cwd: REPO_ROOT,
    encoding: 'utf8',
  });
  const files = stdout.split('\n').filter(Boolean);
  if (files.length === 0) {
    throw new P18InstrumentFailure('R3 found no packaged-docs files — refusing to report success on no input');
  }
  return files;
}

function r3PlanningPathTotal() {
  let total = 0;
  for (const path of packagedDocsFiles()) {
    total += [...readFileSync(resolve(REPO_ROOT, path), 'utf8').matchAll(/\.planning\//g)].length;
  }
  return total;
}

function assertNotIncreased(counter, measured) {
  const baseline = loadBaselines().get(counter);
  console.log(`${counter} measured=${measured} baseline=${baseline} pass=decrease-or-equal zero-is-not-the-target`);
  assert.ok(
    measured <= baseline,
    `P18 RATCHET REGRESSION ${counter}: measured=${measured} exceeds baseline=${baseline}; ` +
      'zero is explicitly not the target, but an increase is a regression.',
  );
}

test('R1: narrower Phase-237 vocabulary in lib doc ranges does not increase', () => {
  const result = docRangeScan('lib');
  assert.ok(
    result.docRanges > 0,
    'P18 INSTRUMENT FAILURE: R1 found zero doc ranges — this is not a clean surface.',
  );
  assertNotIncreased('R1', result.totalHits);
});

test('R2: wide Phase-239 V3 vocabulary in lib comment-only lines does not increase', () => {
  assertNotIncreased('R2', r2CommentLineTotal());
});

test('R3: literal .planning/ occurrences in packaged docs do not increase', () => {
  assertNotIncreased('R3', r3PlanningPathTotal());
});

// P18 (241-06) — prevent new planning-artifact references in HexDocs doc ranges.
//
// This is deliberately narrower than R1's ratchet. The hard-fail asks whether a
// token with zero historical occurrences has appeared; R1 asks whether the known
// historical bookkeeping total is shrinking. Conflating those questions would make
// either instrument dishonest. The list below was measured at execution HEAD: its
// alternatives each measured zero in lib/ doc ranges. Non-zero historical tokens
// (for example `Phase NNN` and `D-NN`) belong to R1, never this hard fail.

import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';

import {
  docRangeScan,
  docRangeTotal,
  P18InstrumentFailure,
} from './_p18-lib.mjs';

const PARITY_MANIFEST_PATH = 'test/fixtures/prohibitions/p18-doc-range-parity.tsv';
const RATCHET_BASELINE_PATH = 'scripts/ci/prohibitions/p18-ratchet-baseline.tsv';

const HARD_FAIL_TOKENS = [
  ['planning directory', /\.planning\//g],
  ['plan artifact filename', /-PLAN\.md/g],
  ['summary artifact filename', /-SUMMARY\.md/g],
  ['todos directory', /\btodos\//g],
  ['lowercase phase identifier', /\bphase[-_]\d{1,3}\b/g],
  ['criterion identifier', /\bSC-\d\b/g],
  ['requirement identifier', /\bREQ-[A-Z0-9]/g],
];

function hardFailViolations(result) {
  const violations = [];
  for (const [label, pattern] of HARD_FAIL_TOKENS) {
    for (const [token, count] of result.tokenHits) {
      if (pattern.test(token)) violations.push(`${label}=${token} (${count})`);
      pattern.lastIndex = 0;
    }
  }
  return violations;
}

function parityRows() {
  const lines = readFileSync(PARITY_MANIFEST_PATH, 'utf8')
    .split('\n')
    .map((line) => line.replace(/\r$/, ''))
    .filter((line) => line !== '' && !line.startsWith('#'));
  const [header, ...rows] = lines;

  assert.equal(
    header,
    'subject\texpected_total_hits\treference',
    'P18 D-30 PARITY: manifest header must name subject, expected_total_hits, and reference',
  );

  return rows.map((row) => {
    const [subject, expectedTotalHits, reference] = row.split('\t');
    assert.ok(
      subject && /^\d+$/.test(expectedTotalHits ?? '') && reference,
      `P18 D-30 PARITY: malformed manifest row ${JSON.stringify(row)}`,
    );
    return { subject, expectedTotalHits: Number(expectedTotalHits), reference };
  });
}

function r1Baseline() {
  const row = readFileSync(RATCHET_BASELINE_PATH, 'utf8')
    .split('\n')
    .map((line) => line.replace(/\r$/, ''))
    .find((line) => line.startsWith('R1\t'));
  const [, baseline] = row?.split('\t') ?? [];

  assert.ok(
    /^\d+$/.test(baseline ?? ''),
    'P18 D-30 PARITY: R1 baseline row must contain a numeric baseline',
  );
  return Number(baseline);
}

test('tracked lib/ doc ranges contain no zero-at-HEAD planning-artifact tokens', () => {
  const result = docRangeScan('lib');
  assert.ok(
    result.docRanges > 0,
    'P18 INSTRUMENT FAILURE: doc-range walker found zero doc ranges — this is not a clean surface.',
  );

  const violations = hardFailViolations(result);

  console.log(
    `doc_ranges=${result.docRanges} total_hits=${result.totalHits} distinct_sites=${result.distinctSites} distinct_files=${result.distinctFiles}`,
  );
  assert.equal(
    violations.length,
    0,
    violations.length === 0
      ? ''
      : `P18 DIRTY SURFACE: doc-range planning artifact ${violations.join(', ')} in ${process.env.GSD_PROHIB_SUBJECT ?? 'lib/'}`,
  );
});

test('doc-range walker distinguishes an instrument failure from a dirty surface', () => {
  assert.ok(P18InstrumentFailure);
});

test('D-30 parity manifest pins every accepted and rejected fixture to Phase-237 totals', () => {
  const rows = parityRows();
  assert.equal(rows.length, 4, 'P18 D-30 PARITY: manifest must cover all four fixture subjects');
  const mismatches = [];

  for (const { subject, expectedTotalHits, reference } of rows) {
    const previousSubject = process.env.GSD_PROHIB_SUBJECT;
    process.env.GSD_PROHIB_SUBJECT = `test/fixtures/prohibitions/${subject}`;

    try {
      const result = docRangeScan('lib');
      if (result.totalHits !== expectedTotalHits) {
        mismatches.push(
          `${subject} expected ${expectedTotalHits} token hit(s) from ${reference}, got ${result.totalHits}`,
        );
      }
    } finally {
      if (previousSubject === undefined) delete process.env.GSD_PROHIB_SUBJECT;
      else process.env.GSD_PROHIB_SUBJECT = previousSubject;
    }
  }

  assert.deepEqual(mismatches, [], `P18 D-30 PARITY: ${mismatches.join('; ')}`);
});

test('D-30 parity compares the real doc-range total to the committed R1 baseline', () => {
  assert.equal(
    docRangeTotal('lib'),
    r1Baseline(),
    'P18 D-30 PARITY: real lib/ total must equal the R1 baseline row',
  );
});

