// P21 (241-03-PLAN.md) — honest-skip documentation parity.
//
// Subject: MAINTAINING.md (substitutable via GSD_PROHIB_SUBJECT). The manifest and
// the delegated p10 guard are always read from their committed, real locations.
// This guard is offline and can be run on a plane: it makes no network call and
// needs neither `gh` nor a token.
//
// Legs 1–3 (id resolution, step-parent, and display-name parity) belong to
// p10-no-undocumented-demotion.test.mjs and are deliberately not duplicated here.
// That guard carries the `example_playwright_shard` matrix-name exception and the
// intervening comments before `install_smoke`'s name; duplicating either parser would
// create a second owner of the same assertion. The manifest `gate` column is likewise
// deliberately not parsed here: evaluating GHA expressions would turn this parity
// guard into a brittle YAML-expression evaluator.

import test from 'node:test';
import assert from 'node:assert/strict';
import { parseSkipManifest, readRepoFile, readSubject } from './_lib.mjs';

const MANIFEST_ROWS_FLOOR = 16;
const DELEGATED_P10_TESTS = [
  'every manifest id resolves to a real construct in ci.yml',
  'every step row names a parent that is itself a manifest job row',
  'display_name matches the construct name ci.yml actually declares',
];

const rows = parseSkipManifest(readRepoFile('.github/ci-skip-manifest.tsv'));
const maintaining = readSubject('MAINTAINING.md');
const p10 = readRepoFile('scripts/ci/prohibitions/p10-no-undocumented-demotion.test.mjs');
const ACTIVE_IDS_START = '<!-- honest-skip-active-ids:start -->';
const ACTIVE_IDS_END = '<!-- honest-skip-active-ids:end -->';

function honestSkipSection(text) {
  const heading = /^### Honest-skip set after Phase 230[^\n]*$/m.exec(text);
  assert.ok(
    heading,
    'MAINTAINING.md has no honest-skip heading — the section locator broke, this is not a pass.',
  );
  const afterHeading = text.slice(heading.index + heading[0].length);
  const nextHeading = /^### /m.exec(afterHeading);
  const section = nextHeading ? afterHeading.slice(0, nextHeading.index) : afterHeading;
  assert.ok(
    section.trim().length > 0,
    'MAINTAINING.md honest-skip section is empty — the section locator broke, this is not a pass.',
  );
  return section;
}

function documentedActiveIds(section) {
  const start = section.indexOf(ACTIVE_IDS_START);
  const end = section.indexOf(ACTIVE_IDS_END);
  assert.ok(
    start >= 0 && end > start,
    'MAINTAINING.md has no delimited active honest-skip id list — the documentation inventory locator broke, this is not a pass.',
  );

  const entries = section.slice(start + ACTIVE_IDS_START.length, end)
    .split('\n')
    .map((line) => /^\s*-\s+`([^`]+)`\s*$/.exec(line))
    .filter(Boolean)
    .map((match) => match[1]);

  assert.ok(entries.length > 0, 'MAINTAINING.md active honest-skip id list is empty — this is not a pass.');
  assert.equal(
    new Set(entries).size,
    entries.length,
    'MAINTAINING.md active honest-skip id list has duplicate entries — it is not a reliable inventory.',
  );
  return new Set(entries);
}

function expectedActiveIds(rows) {
  return new Set(rows.flatMap((row) => row.kind === 'step' ? [row.id, row.parentJobId] : [row.id]));
}

const section = honestSkipSection(maintaining);
const documentedIds = documentedActiveIds(section);
const expectedIds = expectedActiveIds(rows);

test('missing stale and duplicate active ids cannot satisfy documentation parity', () => {
  const target = [...expectedIds][0];
  const line = `- \`${target}\``;
  assert.ok(section.includes(line));
  const missing = documentedActiveIds(section.replace(line, ''));
  assert.ok(!missing.has(target));
  const stale = documentedActiveIds(section.replace(line, '- `stale_browser_body`'));
  assert.ok([...stale].some((id) => !expectedIds.has(id)));
  assert.throws(() => documentedActiveIds(section.replace(line, `${line}\n${line}`)), /duplicate/);
});

test('the manifest and honest-skip section are non-vacuously available', () => {
  assert.ok(
    rows.length >= MANIFEST_ROWS_FLOOR,
    `manifest parsed ${rows.length} rows; expected at least ${MANIFEST_ROWS_FLOOR} — the parse broke, this is not a pass.`,
  );
  assert.ok(
    section.trim().length > 0,
    'honest-skip section is empty — the section locator broke, this is not a pass.',
  );
});

test('the active honest-skip inventory exactly matches manifest ids and required step parents', () => {
  const missing = [...expectedIds].filter((id) => !documentedIds.has(id));
  const stale = [...documentedIds].filter((id) => !expectedIds.has(id));

  assert.deepEqual(
    missing,
    [],
    `MAINTAINING.md active honest-skip ids omit manifest ids or required step parents: ${missing.join(', ')}`,
  );
  assert.deepEqual(
    stale,
    [],
    `MAINTAINING.md documents stale active honest-skip ids absent from the manifest: ${stale.join(', ')}`,
  );
});

test('p10 continues to own the three delegated ci.yml parity legs', () => {
  for (const delegatedTest of DELEGATED_P10_TESTS) {
    assert.ok(
      p10.includes(delegatedTest),
      `p10-no-undocumented-demotion.test.mjs no longer declares \`${delegatedTest}\`. The three legs this guard does not implement are owned there, and their disappearance is a failure of this guard.`,
    );
  }
});

#!/usr/bin/env bash
# Bounded, source-bound Actions canary. Artifacts are parsed as JSON data only.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
RECEIPT_HELPER="${SCRIPT_DIR}/release-receipt.sh"
REPOSITORY="${GITHUB_REPOSITORY:-szTheory/sigra}"
DISPATCH_ATTEMPTED=false
PROBE_ID="${PROBE_ID:-}"
OUTPUT=""
PROOF=""
MODE=""
WORKFLOW_ID=""
EXPECTED_SHA=""
EXPECTED_SHA256=""
SCENARIO="${SCENARIO:-}"
FAILURE_RECEIPT=""
CANCELLATION_RECEIPT=""

fail() {
  echo "release-canary: FAIL: $*" >&2
  if [[ "${MODE:-}" == run && -n "${PROOF:-}" ]]; then
    local blocked_at proof_dir preflight_path reason_code
    blocked_at="$(date -u +"%Y-%m-%dT%H:%M:%SZ")"
    reason_code="$(printf '%s' "$*" | tr '[:upper:] -' '[:lower:]__' | tr -cd 'a-z_')"
    proof_dir="$(dirname "$PROOF")"; mkdir -p "$proof_dir"
    preflight_path="${proof_dir}/250-CANARY-PREFLIGHT.json"
    jq -n --arg at "$blocked_at" --arg reason "$reason_code" --argjson dispatched "$DISPATCH_ATTEMPTED" \
      --slurpfile preflight "$preflight_path" \
      '{schema_version:1,status:"blocked",captured_at:$at,
        preflight:($preflight[0] // {schema_version:1,status:"blocked",reason:"preflight_unavailable"}),
        reason:$reason,dispatch_attempted:$dispatched,receipts:[],credential_values_recorded:false}' \
      | safe_write_json "$PROOF" || true
  fi
  exit 1
}
usage() {
  cat >&2 <<'USAGE'
Usage:
  release-canary.sh --self-test
  release-canary.sh --validate-proof <proof.json>
  release-canary.sh --write-failure-receipt --output <receipt.json>
  release-canary.sh --resolve-run --workflow-id <id> --scenario <failure|cancellation> --probe-id <id>
  release-canary.sh --cancel-canary-run <run-id> --workflow-id <id> --expected-sha <sha>
  release-canary.sh --validate-pair --failure-receipt <json> --cancellation-receipt <json>
  release-canary.sh --preflight --output <preflight.json>
  release-canary.sh --validate-preflight --output <validated-preflight.json>
  release-canary.sh --prepare-preflight-input --output <runner-temp.json> --expected-sha256 <sha256>
  release-canary.sh --run --proof <proof.json>
USAGE
}

while [[ $# -gt 0 ]]; do
  case "$1" in
    --self-test) MODE=self-test; shift ;;
    --validate-proof) MODE=validate-proof; [[ $# -ge 2 ]] || { usage; exit 2; }; PROOF="$2"; shift 2 ;;
    --write-failure-receipt) MODE=write-failure; shift ;;
    --resolve-run) MODE=resolve-run; shift ;;
    --cancel-canary-run) MODE=cancel-canary; [[ $# -ge 2 ]] || { usage; exit 2; }; PROOF="$2"; shift 2 ;;
    --validate-pair) MODE=validate-pair; shift ;;
    --preflight) MODE=preflight; shift ;;
    --validate-preflight) MODE=validate-preflight; shift ;;
    --prepare-preflight-input) MODE=prepare-preflight-input; shift ;;
    --run) MODE=run; shift ;;
    --output) [[ $# -ge 2 ]] || { usage; exit 2; }; OUTPUT="$2"; shift 2 ;;
    --proof) [[ $# -ge 2 ]] || { usage; exit 2; }; PROOF="$2"; shift 2 ;;
    --workflow-id) [[ $# -ge 2 ]] || { usage; exit 2; }; WORKFLOW_ID="$2"; shift 2 ;;
    --expected-sha) [[ $# -ge 2 ]] || { usage; exit 2; }; EXPECTED_SHA="$2"; shift 2 ;;
    --expected-sha256) [[ $# -ge 2 ]] || { usage; exit 2; }; EXPECTED_SHA256="$2"; shift 2 ;;
    --scenario) [[ $# -ge 2 ]] || { usage; exit 2; }; SCENARIO="$2"; shift 2 ;;
    --probe-id) [[ $# -ge 2 ]] || { usage; exit 2; }; PROBE_ID="$2"; shift 2 ;;
    --failure-receipt) [[ $# -ge 2 ]] || { usage; exit 2; }; FAILURE_RECEIPT="$2"; shift 2 ;;
    --cancellation-receipt) [[ $# -ge 2 ]] || { usage; exit 2; }; CANCELLATION_RECEIPT="$2"; shift 2 ;;
    -h|--help) usage; exit 0 ;;
    *) fail "unknown argument" ;;
  esac
done

safe_write_json() {
  local path="$1"
  mkdir -p "$(dirname "$path")"
  local tmp
  tmp="$(mktemp "${path}.tmp.XXXXXX")"
  cat > "$tmp"
  jq -e . "$tmp" >/dev/null || { rm -f "$tmp"; fail "refusing to write invalid JSON"; }
  mv -f "$tmp" "$path"
}

valid_probe_id() { [[ "$1" =~ ^[a-f0-9-]{16,64}$ ]]; }

validate_receipt_pair() {
  local failure="$1" cancellation="$2"
  jq -e 'def timestamp: type == "string" and test("^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$");
    type == "object" and .receipt_kind == "canary" and .scenario == "failure" and
    .terminal_verdict == "failure" and .source_ref == "refs/heads/main" and
    (.source_repository == "szTheory/sigra") and (.source_run_id | type == "string") and (.source_run_attempt | type == "number" and . >= 1) and
    (.source_sha | test("^[0-9a-f]{40}$")) and (.probe_id | test("^[a-f0-9-]{16,64}$")) and
    .source_event == "workflow_dispatch" and .source_workflow_name == "Release Receipt Canary" and
    .source_workflow_path == ".github/workflows/release-receipt-canary.yml" and
    (.source_started_at | timestamp) and (.source_observed_at | timestamp) and
    ([.. | objects | keys[]? | select(test("(token|secret|credential|api.?key)";"i"))] | length == 0)' "$failure" >/dev/null 2>&1 || return 1
  jq -e 'def timestamp: type == "string" and test("^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$");
    type == "object" and .receipt_kind == "canary" and .scenario == "cancellation" and
    .terminal_verdict == "cancelled" and .source_ref == "refs/heads/main" and
    (.source_repository == "szTheory/sigra") and (.source_run_id | type == "string") and (.source_run_attempt | type == "number" and . >= 1) and
    (.source_sha | test("^[0-9a-f]{40}$")) and (.probe_id | test("^[a-f0-9-]{16,64}$")) and
    .source_event == "workflow_dispatch" and .source_workflow_name == "Release Receipt Canary" and
    .source_workflow_path == ".github/workflows/release-receipt-canary.yml" and
    (.source_started_at | timestamp) and (.source_observed_at | timestamp) and
    (.observer_run.id | type == "string") and (.observer_run.attempt | type == "number" and . >= 1) and
    (.observer_run.workflow_id | type == "number" and . > 0) and
    (.observer_run.started_at | timestamp) and (.observer_run.observed_at | timestamp) and
    ([.. | objects | keys[]? | select(test("(token|secret|credential|api.?key)";"i"))] | length == 0)' "$cancellation" >/dev/null 2>&1 || return 1
  [[ "$(jq -r .probe_id "$failure")" != "$(jq -r .probe_id "$cancellation")" ]] || return 1
  [[ "$(jq -r .source_run_id "$failure")" != "$(jq -r .source_run_id "$cancellation")" ]] || return 1
  [[ "$(jq -r .source_sha "$failure")" == "$(jq -r .source_sha "$cancellation")" ]] || return 1
  [[ "$(jq -r .source_run_attempt "$failure")" == "$(jq -r .source_run_attempt "$cancellation")" ]] || return 1
}

write_failure_receipt() {
  [[ -n "${GITHUB_REPOSITORY:-}" && "$GITHUB_REPOSITORY" == "$REPOSITORY" ]] || fail "repository identity missing or mismatched"
  [[ "${GITHUB_EVENT_NAME:-}" == workflow_dispatch && "${GITHUB_REF:-}" == refs/heads/main ]] || fail "source must be workflow_dispatch on main"
  valid_probe_id "$PROBE_ID" || fail "probe ID is malformed"
  [[ "${SCENARIO:-}" == failure ]] || fail "source failure receipt requires the failure scenario"
  [[ -n "${GH_TOKEN:-}" ]] || fail "Actions read token is unavailable"
  [[ -n "$OUTPUT" ]] || fail "output path is required"
  local run workflow jobs id attempt sha branch event workflow_name workflow_path run_name path start observed title step_failure workflow_id
  run="$(gh api "repos/${REPOSITORY}/actions/runs/${GITHUB_RUN_ID}")" || fail "authoritative source run query failed"
  workflow="$(gh api "repos/${REPOSITORY}/actions/workflows/release-receipt-canary.yml")" || fail "authoritative canary workflow query failed"
  workflow_id="$(jq -er '.id | select(type == "number" and floor == . and . > 0)' <<<"$workflow")" || fail "canary workflow ID malformed"
  jobs="$(gh api "repos/${REPOSITORY}/actions/runs/${GITHUB_RUN_ID}/jobs")" || fail "source job identity query failed"
  id="$(jq -er '.id | numbers' <<<"$run")" || fail "source run ID unavailable"
  attempt="$(jq -er '.run_attempt | select(type == "number" and . >= 1 and floor == .)' <<<"$run")" || fail "source attempt unavailable"
  sha="$(jq -er '.head_sha | select(type == "string" and test("^[0-9a-f]{40}$"))' <<<"$run")" || fail "source SHA malformed"
  branch="$(jq -er '.head_branch' <<<"$run")" || fail "source branch unavailable"
  event="$(jq -er '.event' <<<"$run")" || fail "source event unavailable"
  workflow_name="$(jq -er '.name' <<<"$workflow")" || fail "source workflow name unavailable"
  workflow_path="$(jq -er '.path' <<<"$workflow")" || fail "source workflow path unavailable"
  run_name="$(jq -er '.name' <<<"$run")" || fail "source run name unavailable"
  path="$(jq -er '.path' <<<"$run")" || fail "source workflow path unavailable"
  title="$(jq -er '.display_title' <<<"$run")" || fail "source title unavailable"
  [[ "$id" == "$GITHUB_RUN_ID" && "$branch" == main && "$event" == workflow_dispatch ]] || fail "source run identity mismatch"
  [[ "$workflow_name" == "Release Receipt Canary" && "$workflow_path" == .github/workflows/release-receipt-canary.yml ]] || fail "source workflow metadata identity mismatch"
  [[ "$path" =~ ^\.github/workflows/release-receipt-canary\.yml(@main)?$ ]] || fail "source workflow path mismatch"
  [[ "$(jq -er '.id | numbers' <<<"$workflow")" == "$(jq -er '.workflow_id | numbers' <<<"$run")" ]] || fail "source workflow ID mismatch"
  [[ "$run_name" == "release-receipt-canary-failure-${PROBE_ID}" && "$title" == "$run_name" ]] || fail "source run-name or probe title mismatch"
  start="$(jq -er '.run_started_at' <<<"$run" | sed -E 's/\.[0-9]+Z$/Z/')"
  observed="$(date -u +"%Y-%m-%dT%H:%M:%SZ")"
  step_failure="$(jq -r '[.jobs[]?.steps[]? | select(.name == "Controlled failure before release operations") | .conclusion == "failure"] | any' <<<"$jobs")"
  [[ "$step_failure" == true ]] || fail "controlled failure step is not authoritatively failed"
  jq -n --arg probe "$PROBE_ID" --arg id "$GITHUB_RUN_ID" --arg sha "$sha" --arg repository "$REPOSITORY" \
    --arg start "$start" --arg observed "$observed" \
    --arg run_url "https://github.com/${REPOSITORY}/actions/runs/${GITHUB_RUN_ID}" \
    --argjson attempt "$attempt" --argjson workflow_id "$workflow_id" \
    '{schema_version:1,receipt_kind:"canary",canary:{probe_id:$probe,scenario:"failure"},
      source_event:"workflow_dispatch",source:{repository:$repository,ref:"refs/heads/main",sha:$sha},
      source_run:{id:$id,attempt:$attempt,workflow_id:$workflow_id,
        workflow_name:"Release Receipt Canary",workflow_path:".github/workflows/release-receipt-canary.yml",
        url:$run_url,started_at:$start,observed_at:$observed},terminal_verdict:"failure",observer_run:null}' \
    > "${OUTPUT}.input"
  bash "$RECEIPT_HELPER" --mode canary --expected-workflow-id "$workflow_id" --input "${OUTPUT}.input" --output "$OUTPUT"
  rm -f "${OUTPUT}.input"
}

write_blocked_preflight() {
  [[ -n "$OUTPUT" ]] || fail "preflight output path is required"
  local captured reason="$1"
  captured="$(date -u +"%Y-%m-%dT%H:%M:%SZ")"
  jq -n --arg captured "$captured" --arg repository "$REPOSITORY" --arg reason "$reason" \
    '{schema_version:1,status:"blocked",captured_at:$captured,repository:$repository,
      target_ref:"refs/heads/main",workflows:{
        canary:{id:null,path:".github/workflows/release-receipt-canary.yml"},
        controller:{id:null,path:".github/workflows/release-receipt-canary-controller.yml"},
        observer:{id:null,path:".github/workflows/release-run-observer.yml"}},
      reason:$reason,dispatch_attempted:false,credential_values_recorded:false}' | safe_write_json "$OUTPUT"
  echo "release-canary: preflight blocked (${reason})" >&2
}

run_preflight() {
  [[ -n "$OUTPUT" ]] || fail "preflight output path is required"
  command -v gh >/dev/null 2>&1 || { write_blocked_preflight gh_unavailable; return 0; }
  [[ "$REPOSITORY" == szTheory/sigra ]] || { write_blocked_preflight repository_identity_mismatch; return 0; }
  local repo workflow source controller observer workflow_perms actions_perms retention_policy retention retention_maximum captured main_sha
  repo="$(gh api "repos/${REPOSITORY}" 2>/dev/null)" || { write_blocked_preflight repository_metadata_unavailable; return 0; }
  workflow="$(gh api "repos/${REPOSITORY}/actions/workflows/release-receipt-canary.yml" 2>/dev/null)" || { write_blocked_preflight canary_workflow_not_visible; return 0; }
  controller="$(gh api "repos/${REPOSITORY}/actions/workflows/release-receipt-canary-controller.yml" 2>/dev/null)" || { write_blocked_preflight controller_workflow_not_visible; return 0; }
  observer="$(gh api "repos/${REPOSITORY}/actions/workflows/release-run-observer.yml" 2>/dev/null)" || { write_blocked_preflight observer_workflow_not_visible; return 0; }
  workflow_perms="$(gh api "repos/${REPOSITORY}/actions/permissions/workflow" 2>/dev/null)" || { write_blocked_preflight workflow_permissions_unreadable; return 0; }
  actions_perms="$(gh api "repos/${REPOSITORY}/actions/permissions" 2>/dev/null)" || { write_blocked_preflight actions_settings_unreadable; return 0; }
  retention_policy="$(gh api "repos/${REPOSITORY}/actions/permissions/artifact-and-log-retention" 2>/dev/null)" || { write_blocked_preflight artifact_retention_unreadable; return 0; }
  retention="$(jq -er '.days | select(type == "number" and . >= 30)' <<<"$retention_policy" 2>/dev/null)" || { write_blocked_preflight artifact_retention_below_30_days_or_unreadable; return 0; }
  retention_maximum="$(jq -er '.maximum_allowed_days | select(type == "number" and . >= 30)' <<<"$retention_policy" 2>/dev/null)" || { write_blocked_preflight artifact_retention_maximum_unreadable; return 0; }
  [[ "$(jq -r '.default_branch // empty' <<<"$repo")" == main ]] || { write_blocked_preflight default_branch_not_main; return 0; }
  [[ "$(jq -r '.enabled // false' <<<"$actions_perms")" == true ]] || { write_blocked_preflight actions_disabled; return 0; }
  [[ "$(jq -r '.name // empty' <<<"$workflow")" == "Release Receipt Canary" && "$(jq -r '.path // empty' <<<"$workflow")" == .github/workflows/release-receipt-canary.yml ]] || { write_blocked_preflight canary_identity_mismatch; return 0; }
  [[ "$(jq -r '.name // empty' <<<"$controller")" == "Release Receipt Canary Controller" && "$(jq -r '.path // empty' <<<"$controller")" == .github/workflows/release-receipt-canary-controller.yml ]] || { write_blocked_preflight controller_identity_mismatch; return 0; }
  [[ "$(jq -r '.name // empty' <<<"$observer")" == "Release Run Observer" && "$(jq -r '.path // empty' <<<"$observer")" == .github/workflows/release-run-observer.yml ]] || { write_blocked_preflight observer_identity_mismatch; return 0; }
  [[ "$(jq -r '.default_workflow_permissions // empty' <<<"$workflow_perms")" == read ]] || { write_blocked_preflight default_workflow_permissions_not_read; return 0; }
  main_sha="$(gh api "repos/${REPOSITORY}/commits/main" --jq .sha 2>/dev/null)" || { write_blocked_preflight default_branch_sha_unavailable; return 0; }
  [[ "$main_sha" =~ ^[0-9a-f]{40}$ ]] || { write_blocked_preflight default_branch_sha_malformed; return 0; }
  captured="$(date -u +"%Y-%m-%dT%H:%M:%SZ")"
  jq -n --arg captured "$captured" --arg repo "$REPOSITORY" --arg main_sha "$main_sha" --argjson retention "$retention" \
    --argjson retention_maximum "$retention_maximum" \
    --argjson canary_id "$(jq -r '.id' <<<"$workflow")" \
    --argjson controller_id "$(jq -r '.id' <<<"$controller")" \
    --argjson observer_id "$(jq -r '.id' <<<"$observer")" \
    '{schema_version:1,status:"ready",captured_at:$captured,repository:$repo,default_branch:"main",target_sha:$main_sha,
      actions_enabled:true,
      artifact_retention_days:$retention,artifact_retention_maximum_days:$retention_maximum,required_retention_days:30,
      workflows:{canary:{id:$canary_id,path:".github/workflows/release-receipt-canary.yml"},
        controller:{id:$controller_id,path:".github/workflows/release-receipt-canary-controller.yml"},
        observer:{id:$observer_id,path:".github/workflows/release-run-observer.yml"}},
      default_workflow_permissions:"read",controller_authority:"actions:write; contents:read",
      source_authority:"actions:read; contents:read",observer_authority:"actions:read; contents:read",
      credential_values_recorded:false,dispatch_attempted:false}' | safe_write_json "$OUTPUT"
}

validate_committed_preflight() {
  local source_path="${CANARY_PREFLIGHT_FILE:-$ROOT/.planning/phases/250-close-v1-49-audit-gaps-reconcile-phase-247-248-249-verificat/250-CANARY-PREFLIGHT.json}"
  local target_path="$1" preflight captured captured_epoch now age repo canary controller observer main_sha current_sha
  OUTPUT="$target_path"
  [[ -f "$source_path" ]] || { write_blocked_preflight committed_preflight_missing; return 1; }
  cp "$source_path" "$target_path"
  preflight="$target_path"
  jq -e 'type == "object" and .schema_version == 1 and .status == "ready" and
    .repository == "szTheory/sigra" and .default_branch == "main" and
    (.target_sha | type == "string" and test("^[0-9a-f]{40}$")) and
    (.artifact_retention_days | type == "number" and . >= 30) and
    (.artifact_retention_maximum_days | type == "number" and . >= 30) and
    .actions_enabled == true and .default_workflow_permissions == "read" and
    .controller_authority == "actions:write; contents:read" and
    .source_authority == "actions:read; contents:read" and .observer_authority == "actions:read; contents:read" and
    .dispatch_attempted == false and .credential_values_recorded == false' \
    "$preflight" >/dev/null 2>&1 || { write_blocked_preflight committed_preflight_invalid; return 1; }
  captured="$(jq -er '.captured_at | select(type == "string" and test("^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$"))' "$preflight")" || { write_blocked_preflight committed_preflight_timestamp_invalid; return 1; }
  captured_epoch="$(date -u -j -f '%Y-%m-%dT%H:%M:%SZ' "$captured" '+%s' 2>/dev/null || date -u -d "$captured" '+%s' 2>/dev/null)" || { write_blocked_preflight committed_preflight_timestamp_invalid; return 1; }
  now="$(date -u '+%s')"; age=$((now - captured_epoch))
  (( age >= 0 && age <= 900 )) || { write_blocked_preflight committed_preflight_stale; return 1; }

  repo="$(gh api "repos/${REPOSITORY}" 2>/dev/null)" || { write_blocked_preflight repository_metadata_unavailable; return 1; }
  [[ "$(jq -r '.default_branch // empty' <<<"$repo")" == main ]] || { write_blocked_preflight default_branch_not_main; return 1; }
  canary="$(gh api "repos/${REPOSITORY}/actions/workflows/release-receipt-canary.yml" 2>/dev/null)" || { write_blocked_preflight canary_workflow_not_visible; return 1; }
  controller="$(gh api "repos/${REPOSITORY}/actions/workflows/release-receipt-canary-controller.yml" 2>/dev/null)" || { write_blocked_preflight controller_workflow_not_visible; return 1; }
  observer="$(gh api "repos/${REPOSITORY}/actions/workflows/release-run-observer.yml" 2>/dev/null)" || { write_blocked_preflight observer_workflow_not_visible; return 1; }
  [[ "$(jq -r '.id' <<<"$canary")" == "$(jq -r '.workflows.canary.id' "$preflight")" && "$(jq -r '.path' <<<"$canary")" == .github/workflows/release-receipt-canary.yml && "$(jq -r '.name' <<<"$canary")" == 'Release Receipt Canary' ]] || { write_blocked_preflight canary_identity_changed; return 1; }
  [[ "$(jq -r '.id' <<<"$controller")" == "$(jq -r '.workflows.controller.id' "$preflight")" && "$(jq -r '.path' <<<"$controller")" == .github/workflows/release-receipt-canary-controller.yml && "$(jq -r '.name' <<<"$controller")" == 'Release Receipt Canary Controller' ]] || { write_blocked_preflight controller_identity_changed; return 1; }
  [[ "$(jq -r '.id' <<<"$observer")" == "$(jq -r '.workflows.observer.id' "$preflight")" && "$(jq -r '.path' <<<"$observer")" == .github/workflows/release-run-observer.yml && "$(jq -r '.name' <<<"$observer")" == 'Release Run Observer' ]] || { write_blocked_preflight observer_identity_changed; return 1; }
  main_sha="$(gh api "repos/${REPOSITORY}/commits/main" --jq .sha 2>/dev/null)" || { write_blocked_preflight default_branch_sha_unavailable; return 1; }
  current_sha="$(git -C "$ROOT" rev-parse HEAD 2>/dev/null)" || { write_blocked_preflight controller_checkout_sha_unavailable; return 1; }
  [[ "$current_sha" == "$main_sha" ]] || { write_blocked_preflight controller_checkout_not_current_main; return 1; }
  local target_sha file target_blob current_blob
  target_sha="$(jq -r '.target_sha' "$preflight")"
  git -C "$ROOT" merge-base --is-ancestor "$target_sha" "$current_sha" 2>/dev/null || { write_blocked_preflight default_branch_rewound_after_preflight; return 1; }
  for file in \
    .github/workflows/release-receipt-canary.yml \
    .github/workflows/release-receipt-canary-controller.yml \
    .github/workflows/release-run-observer.yml \
    scripts/ci/release-canary.sh \
    scripts/ci/release-canary.test.sh \
    scripts/ci/release-observer.sh \
    scripts/ci/release-receipt.sh \
    test/sigra/planning/phase_248_release_observer_contract_test.exs \
    test/sigra/planning/phase_250_canary_contract_test.exs; do
    target_blob="$(git -C "$ROOT" rev-parse "${target_sha}:${file}" 2>/dev/null)" || { write_blocked_preflight preflight_source_blob_unavailable; return 1; }
    current_blob="$(git -C "$ROOT" rev-parse "${current_sha}:${file}" 2>/dev/null)" || { write_blocked_preflight current_source_blob_unavailable; return 1; }
    [[ "$target_blob" == "$current_blob" ]] || { write_blocked_preflight canary_source_changed_after_preflight; return 1; }
  done
}

prepare_preflight_input() {
  local payload="${CANARY_PREFLIGHT_JSON:-}" supplied_digest="${CANARY_PREFLIGHT_SHA256:-}"
  local actual_digest byte_count tmp written_digest
  [[ -n "$OUTPUT" && -n "${RUNNER_TEMP:-}" && "$OUTPUT" == "$RUNNER_TEMP/"* ]] || fail "preflight input output must be under RUNNER_TEMP"
  [[ -n "$payload" && "${#payload}" -le 32768 ]] || fail "preflight input is empty or exceeds the 32768-byte limit"
  [[ "$supplied_digest" =~ ^[0-9a-f]{64}$ && "$EXPECTED_SHA256" == "$supplied_digest" ]] || fail "preflight input digest is malformed or inconsistent"
  byte_count="$(LC_ALL=C printf '%s' "$payload" | wc -c | tr -d ' ')"
  (( byte_count > 0 && byte_count <= 32768 )) || fail "preflight input is empty or exceeds the 32768-byte limit"
  actual_digest="$(printf '%s' "$payload" | (sha256sum 2>/dev/null || shasum -a 256) | awk '{print $1}')"
  [[ "$actual_digest" == "$supplied_digest" ]] || fail "preflight input digest mismatch"
  printf '%s' "$payload" | jq -es '
    def no_credential_keys:
      [.. | objects | to_entries[] |
        select((.key | test("(token|secret|credential|api.?key)";"i")) and
          (.key != "credential_values_recorded" or .value != false))] | length == 0;
    length == 1 and (.[0] | type == "object" and .schema_version == 1 and .status == "ready" and
      .repository == "szTheory/sigra" and .default_branch == "main" and
      (.target_sha | type == "string" and test("^[0-9a-f]{40}$")) and
      (.captured_at | type == "string" and test("^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$")) and
      (.workflows.canary.id | type == "number" and floor == . and . > 0) and
      .workflows.canary.path == ".github/workflows/release-receipt-canary.yml" and
      (.workflows.controller.id | type == "number" and floor == . and . > 0) and
      .workflows.controller.path == ".github/workflows/release-receipt-canary-controller.yml" and
      (.workflows.observer.id | type == "number" and floor == . and . > 0) and
      .workflows.observer.path == ".github/workflows/release-run-observer.yml" and
      .credential_values_recorded == false and .dispatch_attempted == false and no_credential_keys)
  ' >/dev/null 2>&1 || fail "preflight input is malformed, mismatched, or contains credential-shaped fields"
  mkdir -p "$(dirname "$OUTPUT")"
  umask 077
  tmp="$(mktemp "${OUTPUT}.tmp.XXXXXX")"
  printf '%s' "$payload" > "$tmp"
  written_digest="$( (sha256sum "$tmp" 2>/dev/null || shasum -a 256 "$tmp") | awk '{print $1}')"
  [[ "$written_digest" == "$supplied_digest" ]] || { rm -f "$tmp"; fail "preflight input changed while writing"; }
  mv "$tmp" "$OUTPUT"
  echo "release-canary: preflight input accepted"
}

validate_exact_run_identity() {
  local run_json="$1" workflow_id="$2" title="$3" expected_sha="$4"
  jq -e --argjson workflow_id "$workflow_id" --arg title "$title" --arg sha "$expected_sha" '
    (.id | type == "number" and floor == . and . > 0) and
    .workflow_id == $workflow_id and
    (.path | type == "string") and (.path | sub("@.*$"; "")) == ".github/workflows/release-receipt-canary.yml" and
    .name == $title and .display_title == $title and
    .event == "workflow_dispatch" and .head_branch == "main" and .head_sha == $sha and
    .run_attempt == 1
  ' <<<"$run_json" >/dev/null 2>&1
}

find_exact_run() {
  local workflow_id="$1" title="$2" expected_sha="$3" response matches count elapsed=0
  while (( elapsed <= 600 )); do
    response="$(gh api "repos/${REPOSITORY}/actions/workflows/${workflow_id}/runs?branch=main&event=workflow_dispatch&per_page=100")" || return 1
    count="$(jq -er --arg title "$title" '[.workflow_runs[]? | select(.display_title == $title)] | length' <<<"$response")" || return 1
    if (( count == 1 )); then
      matches="$(jq -cer --arg title "$title" '[.workflow_runs[]? | select(.display_title == $title)][0]' <<<"$response")" || return 1
      if ! validate_exact_run_identity "$matches" "$workflow_id" "$title" "$expected_sha"; then
        echo "release-canary: exact-title run source identity mismatch" >&2
        return 3
      fi
      matches="$(jq -er '.id | select(type == "number" and floor == . and . > 0)' <<<"$matches")" || return 1
      printf '%s' "$matches"
      return 0
    fi
    # A repeated exact title is ambiguous and must fail immediately. Zero matches
    # can be GitHub's short dispatch-indexing delay, so poll for at most 10 minutes.
    (( count == 0 )) || { echo "release-canary: exact-title run is ambiguous" >&2; return 2; }
    (( elapsed < 600 )) || return 1
    sleep 60
    elapsed=$((elapsed + 60))
  done
  return 1
}

dispatch_probe() {
  local scenario="$1" probe="$2" workflow_id="$3" expected_sha="$4" response id run title
  response="$(gh api --method POST "repos/${REPOSITORY}/actions/workflows/${workflow_id}/dispatches" \
    -f ref=main -f "inputs[scenario]=${scenario}" -f "inputs[probe_id]=${probe}")" || return 1
  id="$(jq -r '.workflow_run_id // .run_id // empty' <<<"$response" 2>/dev/null || true)"
  title="release-receipt-canary-${scenario}-${probe}"
  if [[ "$id" =~ ^[1-9][0-9]*$ ]]; then
    run="$(run_metadata "$id")" || return 1
    validate_exact_run_identity "$run" "$workflow_id" "$title" "$expected_sha" || return 3
    printf '%s' "$id"
    return 0
  fi
  find_exact_run "$workflow_id" "$title" "$expected_sha"
}

watch_run() {
  local id="$1"
  set +e
  gh run watch "$id" --repo "$REPOSITORY" --compact --interval 60 --exit-status >/dev/null
  local rc=$?
  set -e
  # A failure/cancellation exit code is expected only after its authoritative
  # conclusion is checked by the caller.
  return 0
}

run_metadata() {
  gh api "repos/${REPOSITORY}/actions/runs/$1"
}

run_jobs() {
  gh api "repos/${REPOSITORY}/actions/runs/$1/jobs"
}

get_unique_artifact() {
  local run_id="$1" expected_name="$2" listing
  listing="$(gh api "repos/${REPOSITORY}/actions/runs/${run_id}/artifacts")" || return 1
  jq -er --arg name "$expected_name" '
    [.artifacts[]? | select(.name == $name and .expired == false)] |
    if length == 1 then .[0] else error("artifact identity is absent or ambiguous") end
  ' <<<"$listing"
}

download_receipt_artifact() {
  local artifact_json="$1" target_dir="$2" artifact_id name expected_digest actual_digest zip
  artifact_id="$(jq -er '.id | select(type == "number" and floor == . and . > 0)' <<<"$artifact_json")" || return 1
  name="$(jq -er '.name | select(type == "string")' <<<"$artifact_json")" || return 1
  expected_digest="$(jq -er '.digest | select(type == "string" and test("^sha256:[0-9a-f]{64}$")) | sub("^sha256:"; "")' <<<"$artifact_json")" || return 1
  zip="${target_dir}/artifact-${artifact_id}.zip"
  mkdir -p "$target_dir"
  gh api "repos/${REPOSITORY}/actions/artifacts/${artifact_id}/zip" --output "$zip" >/dev/null || return 1
  actual_digest="$(shasum -a 256 "$zip" | awk '{print $1}')"
  [[ "$actual_digest" == "$expected_digest" ]] || return 1
  unzip -p "$zip" canary-receipt.json > "${target_dir}/receipt.json" || return 1
  jq -e 'type == "object" and .receipt_kind == "canary"' "${target_dir}/receipt.json" >/dev/null || return 1
  printf '%s\n' "$name"
}

wait_for_cancellation_stage() {
  local id="$1" jobs run elapsed=0
  while (( elapsed <= 600 )); do
    run="$(run_metadata "$id")" || return 1
    [[ "$(jq -r '.id | tostring' <<<"$run")" == "$id" && "$(jq -r '.head_branch' <<<"$run")" == main && "$(jq -r '.event' <<<"$run")" == workflow_dispatch && "$(jq -r '.status' <<<"$run")" == in_progress ]] || return 1
    jobs="$(run_jobs "$id")" || return 1
    if jq -e '[.jobs[]?.steps[]? | select(.name == "Bounded cancellation wait" and .status == "in_progress")] | length == 1' <<<"$jobs" >/dev/null; then return 0; fi
    sleep 60
    elapsed=$((elapsed + 60))
  done
  return 1
}

cancel_exact_canary_run() {
  local id="$1" expected_workflow_id="$2" expected_probe_id="$3" expected_sha="$4" run jobs
  [[ "$id" =~ ^[1-9][0-9]*$ && "$expected_workflow_id" =~ ^[1-9][0-9]*$ ]] || return 1
  valid_probe_id "$expected_probe_id" || return 1
  [[ "$expected_sha" =~ ^[0-9a-f]{40}$ ]] || return 1
  run="$(run_metadata "$id")" || return 1
  [[ "$(jq -r '.id | tostring' <<<"$run")" == "$id" &&
     "$(jq -r '.workflow_id | tostring' <<<"$run")" == "$expected_workflow_id" &&
     "$(jq -r '.path | sub("@main$";"")' <<<"$run")" == .github/workflows/release-receipt-canary.yml &&
     "$(jq -r '.name' <<<"$run")" == "release-receipt-canary-cancellation-${expected_probe_id}" &&
     "$(jq -r '.event' <<<"$run")" == workflow_dispatch &&
     "$(jq -r '.head_branch' <<<"$run")" == main &&
     "$(jq -r '.head_sha' <<<"$run")" == "$expected_sha" &&
     "$(jq -r '.run_attempt' <<<"$run")" == 1 &&
     "$(jq -r '.display_title' <<<"$run")" == "release-receipt-canary-cancellation-${expected_probe_id}" &&
     "$(jq -r '.status' <<<"$run")" == in_progress ]] || return 1
  jobs="$(run_jobs "$id")" || return 1
  jq -e '[.jobs[]?.steps[]? | select(.name == "Bounded cancellation wait" and .status == "in_progress")] | length == 1' <<<"$jobs" >/dev/null || return 1
  gh api --method POST "repos/${REPOSITORY}/actions/runs/${id}/cancel" >/dev/null
}

wait_for_observer() {
  local source_id="$1" observer_workflow_id="$2" listing matches elapsed=0
  while (( elapsed <= 600 )); do
    listing="$(gh api "repos/${REPOSITORY}/actions/workflows/${observer_workflow_id}/runs?branch=main&event=workflow_run&per_page=100")" || return 1
    matches="$(jq -r --arg prefix "release-observer-${source_id}-" '[.workflow_runs[]? | select(.display_title | startswith($prefix))] | if length == 1 then .[0].id else empty end' <<<"$listing")"
    if [[ "$matches" =~ ^[1-9][0-9]*$ ]]; then printf '%s' "$matches"; return 0; fi
    sleep 60
    elapsed=$((elapsed + 60))
  done
  return 1
}

run_controller() {
  [[ "${GITHUB_EVENT_NAME:-}" == workflow_dispatch && "${GITHUB_REF:-}" == refs/heads/main ]] || fail "controller must run from workflow_dispatch on main"
  local proof_dir preflight_path rate core_remaining canary_wf_id observer_wf_id
  proof_dir="$(dirname "$PROOF")"; mkdir -p "$proof_dir"
  preflight_path="${proof_dir}/250-CANARY-PREFLIGHT.json"
  validate_committed_preflight "$preflight_path" || fail "fresh committed read-only Actions preflight is blocked"
  rate="$(gh api rate_limit)" || fail "GitHub rate-limit preflight unavailable"
  core_remaining="$(jq -er '.resources.core.remaining | select(type == "number")' <<<"$rate")" || fail "GitHub core rate budget unavailable"
  (( core_remaining > 250 )) || fail "GitHub core rate budget is at or below the 250-request stop threshold"
  canary_wf_id="$(jq -er '.workflows.canary.id' "$preflight_path")"
  observer_wf_id="$(jq -er '.workflows.observer.id' "$preflight_path")"
  local sha failure_probe cancel_probe failure_id cancel_id failure_run cancel_run failure_artifact cancel_artifact observer_id observer_run observer_artifact
  local tmp failure_name cancel_name expected_failure_name expected_cancel_name failure_receipt cancel_receipt
  sha="$(gh api "repos/${REPOSITORY}/commits/main" --jq .sha)" || fail "default-branch SHA unavailable"
  [[ "$sha" =~ ^[0-9a-f]{40}$ ]] || fail "default-branch SHA malformed"
  failure_probe="$(openssl rand -hex 16)"; cancel_probe="$(openssl rand -hex 16)"
  [[ "$failure_probe" != "$cancel_probe" ]] || fail "unique probe generation collided"
  expected_failure_name="release-canary-failure-"; expected_cancel_name="release-canary-cancellation-"

  DISPATCH_ATTEMPTED=true
  failure_id="$(dispatch_probe failure "$failure_probe" "$canary_wf_id" "$sha")" || fail "failure probe dispatch correlation failed (zero, ambiguous, or mismatched source identity)"
  watch_run "$failure_id"
  failure_run="$(run_metadata "$failure_id")" || fail "failure run summary unavailable"
  [[ "$(jq -r '.id | tostring' <<<"$failure_run")" == "$failure_id" && "$(jq -r '.workflow_id | tostring' <<<"$failure_run")" == "$canary_wf_id" && "$(jq -r '.path | sub("@main$";"")' <<<"$failure_run")" == .github/workflows/release-receipt-canary.yml && "$(jq -r '.name' <<<"$failure_run")" == "release-receipt-canary-failure-${failure_probe}" && "$(jq -r '.event' <<<"$failure_run")" == workflow_dispatch && "$(jq -r '.head_branch' <<<"$failure_run")" == main && "$(jq -r '.head_sha' <<<"$failure_run")" == "$sha" && "$(jq -r '.run_attempt' <<<"$failure_run")" == 1 && "$(jq -r '.display_title' <<<"$failure_run")" == "release-receipt-canary-failure-${failure_probe}" && "$(jq -r '.conclusion' <<<"$failure_run")" == failure ]] || fail "failure run exact identity or expected conclusion mismatch"
  expected_failure_name="${expected_failure_name}${failure_id}-1-${failure_probe}"
  failure_artifact="$(get_unique_artifact "$failure_id" "$expected_failure_name")" || fail "failure receipt artifact absent or ambiguous"

  cancel_id="$(dispatch_probe cancellation "$cancel_probe" "$canary_wf_id" "$sha")" || fail "cancellation probe dispatch correlation failed (zero, ambiguous, or mismatched source identity)"
  [[ "$cancel_id" != "$failure_id" ]] || fail "probe runs unexpectedly share one run ID"
  wait_for_cancellation_stage "$cancel_id" || fail "exact cancellation probe did not reach its bounded wait stage"
  # Re-query the authoritative run and exact wait step immediately before cancel.
  cancel_exact_canary_run "$cancel_id" "$canary_wf_id" "$cancel_probe" "$sha" || fail "ordinary exact-run cancellation request failed"
  watch_run "$cancel_id"
  cancel_run="$(run_metadata "$cancel_id")" || fail "cancellation run summary unavailable"
  [[ "$(jq -r '.id | tostring' <<<"$cancel_run")" == "$cancel_id" && "$(jq -r '.workflow_id | tostring' <<<"$cancel_run")" == "$canary_wf_id" && "$(jq -r '.path | sub("@main$";"")' <<<"$cancel_run")" == .github/workflows/release-receipt-canary.yml && "$(jq -r '.name' <<<"$cancel_run")" == "release-receipt-canary-cancellation-${cancel_probe}" && "$(jq -r '.event' <<<"$cancel_run")" == workflow_dispatch && "$(jq -r '.head_branch' <<<"$cancel_run")" == main && "$(jq -r '.head_sha' <<<"$cancel_run")" == "$sha" && "$(jq -r '.run_attempt' <<<"$cancel_run")" == 1 && "$(jq -r '.display_title' <<<"$cancel_run")" == "release-receipt-canary-cancellation-${cancel_probe}" && "$(jq -r '.conclusion' <<<"$cancel_run")" == cancelled ]] || fail "cancellation run exact identity or expected conclusion mismatch"

  observer_id="$(wait_for_observer "$cancel_id" "$observer_wf_id")" || fail "exact cancellation observer run was not found"
  watch_run "$observer_id"
  observer_run="$(run_metadata "$observer_id")" || fail "observer run summary unavailable"
  [[ "$(jq -r '.id | tostring' <<<"$observer_run")" == "$observer_id" && "$(jq -r '.workflow_id | tostring' <<<"$observer_run")" == "$observer_wf_id" && "$(jq -r '.path' <<<"$observer_run")" == .github/workflows/release-run-observer.yml && "$(jq -r '.event' <<<"$observer_run")" == workflow_run && "$(jq -r '.head_branch' <<<"$observer_run")" == main && "$(jq -r '.conclusion' <<<"$observer_run")" == success ]] || fail "observer run exact identity or conclusion mismatch"
  expected_cancel_name="${expected_cancel_name}${cancel_id}-1"
  cancel_artifact="$(get_unique_artifact "$observer_id" "$expected_cancel_name")" || fail "observer cancellation artifact absent or ambiguous"

  tmp="$(mktemp -d)"; trap 'rm -rf "$tmp"' RETURN
  failure_name="$(download_receipt_artifact "$failure_artifact" "$tmp/failure")" || fail "failure receipt digest or JSON validation failed"
  cancel_name="$(download_receipt_artifact "$cancel_artifact" "$tmp/cancellation")" || fail "cancellation receipt digest or JSON validation failed"
  failure_receipt="$tmp/failure/receipt.json"; cancel_receipt="$tmp/cancellation/receipt.json"
  validate_receipt_pair "$failure_receipt" "$cancel_receipt" || fail "hosted receipt identities, namespaces, or outcomes disagree"
  [[ "$(jq -r '.source_run_id' "$failure_receipt")" == "$failure_id" && "$(jq -r '.source_run_attempt' "$failure_receipt")" == 1 && "$(jq -r '.source_workflow_id' "$failure_receipt")" == "$canary_wf_id" && "$(jq -r '.source_sha' "$failure_receipt")" == "$sha" && "$(jq -r '.probe_id' "$failure_receipt")" == "$failure_probe" ]] || fail "failure receipt source identity mismatch"
  [[ "$(jq -r '.source_run_id' "$cancel_receipt")" == "$cancel_id" && "$(jq -r '.source_run_attempt' "$cancel_receipt")" == 1 && "$(jq -r '.source_workflow_id' "$cancel_receipt")" == "$canary_wf_id" && "$(jq -r '.source_sha' "$cancel_receipt")" == "$sha" && "$(jq -r '.probe_id' "$cancel_receipt")" == "$cancel_probe" && "$(jq -r '.observer_run.id' "$cancel_receipt")" == "$observer_id" ]] || fail "cancellation receipt source/observer identity mismatch"

  local captured failure_artifact_id cancel_artifact_id failure_artifact_digest cancel_artifact_digest failure_expiry cancel_expiry
  captured="$(date -u +"%Y-%m-%dT%H:%M:%SZ")"
  failure_artifact_id="$(jq -r '.id' <<<"$failure_artifact")"; cancel_artifact_id="$(jq -r '.id' <<<"$cancel_artifact")"
  failure_artifact_digest="$(jq -r '.digest' <<<"$failure_artifact")"; cancel_artifact_digest="$(jq -r '.digest' <<<"$cancel_artifact")"
  failure_expiry="$(jq -r '.expires_at' <<<"$failure_artifact")"; cancel_expiry="$(jq -r '.expires_at' <<<"$cancel_artifact")"
  jq -n --arg captured "$captured" --slurpfile preflight "$preflight_path" \
    --argjson failure_run "$failure_run" --argjson cancel_run "$cancel_run" --argjson observer_run "$observer_run" \
    --argjson failure_artifact "$failure_artifact" --argjson cancel_artifact "$cancel_artifact" \
    --slurpfile failure_receipt "$failure_receipt" --slurpfile cancel_receipt "$cancel_receipt" \
    '{schema_version:1,status:"pass",captured_at:$captured,preflight:$preflight[0],
      source_failure:{run_id:($failure_run.id|tostring),attempt:$failure_run.run_attempt,workflow_id:$failure_run.workflow_id,
        workflow_path:$failure_run.path,event:$failure_run.event,ref:("refs/heads/"+$failure_run.head_branch),sha:$failure_run.head_sha,
        conclusion:$failure_run.conclusion,created_at:$failure_run.created_at,updated_at:$failure_run.updated_at,
        artifact:{id:$failure_artifact.id,name:$failure_artifact.name,digest:$failure_artifact.digest,expires_at:$failure_artifact.expires_at},
        receipt:$failure_receipt[0]},
      source_cancellation:{run_id:($cancel_run.id|tostring),attempt:$cancel_run.run_attempt,workflow_id:$cancel_run.workflow_id,
        workflow_path:$cancel_run.path,event:$cancel_run.event,ref:("refs/heads/"+$cancel_run.head_branch),sha:$cancel_run.head_sha,
        conclusion:$cancel_run.conclusion,created_at:$cancel_run.created_at,updated_at:$cancel_run.updated_at,
        artifact:{id:$cancel_artifact.id,name:$cancel_artifact.name,digest:$cancel_artifact.digest,expires_at:$cancel_artifact.expires_at},
        observer_run_id:($observer_run.id|tostring),observer_attempt:$observer_run.run_attempt,
        observer_workflow_id:$observer_run.workflow_id,observer_workflow_path:$observer_run.path,
        observer_event:$observer_run.event,observer_ref:("refs/heads/"+$observer_run.head_branch),
        observer_conclusion:$observer_run.conclusion,receipt:$cancel_receipt[0]},
      retrieval:{failure_artifact_name:$failure_artifact.name,cancellation_artifact_name:$cancel_artifact.name,
        retrieved_at:$captured,failure_zip_sha256:($failure_artifact.digest|sub("^sha256:";"")),
        cancellation_zip_sha256:($cancel_artifact.digest|sub("^sha256:";""))},
      credential_values_recorded:false}' | safe_write_json "$PROOF"
  bash "$0" --validate-proof "$PROOF"
}

case "$MODE" in
  resolve-run)
    [[ "$WORKFLOW_ID" =~ ^[1-9][0-9]*$ ]] || fail "workflow ID is malformed"
    [[ "$SCENARIO" == failure || "$SCENARIO" == cancellation ]] || fail "scenario is invalid"
    valid_probe_id "$PROBE_ID" || fail "probe ID is malformed"
    [[ "$EXPECTED_SHA" =~ ^[0-9a-f]{40}$ ]] || fail "expected source SHA is malformed"
    exact_title="release-receipt-canary-${SCENARIO}-${PROBE_ID}"
    exact_run="$(find_exact_run "$WORKFLOW_ID" "$exact_title" "$EXPECTED_SHA")" || fail "probe run correlation rejected (zero, ambiguous, or mismatched source identity)"
    printf '%s\n' "$exact_run"
    ;;
  cancel-canary)
    [[ "$PROOF" =~ ^[1-9][0-9]*$ ]] || fail "run ID is malformed"
    [[ "$WORKFLOW_ID" =~ ^[1-9][0-9]*$ ]] || fail "workflow ID is malformed"
    valid_probe_id "$PROBE_ID" || fail "probe ID is malformed"
    [[ "$EXPECTED_SHA" =~ ^[0-9a-f]{40}$ ]] || fail "expected source SHA is malformed"
    cancel_exact_canary_run "$PROOF" "$WORKFLOW_ID" "$PROBE_ID" "$EXPECTED_SHA" || fail "refusing to cancel a non-canary or non-waiting run"
    echo "release-canary: cancelled exact canary run ${PROOF}"
    ;;
  validate-pair)
    [[ -n "$FAILURE_RECEIPT" && -f "$FAILURE_RECEIPT" && -n "$CANCELLATION_RECEIPT" && -f "$CANCELLATION_RECEIPT" ]] || fail "both receipt files are required"
    validate_receipt_pair "$FAILURE_RECEIPT" "$CANCELLATION_RECEIPT" || fail "receipt pair identity or outcome mismatch"
    echo "release-canary: receipt pair PASS"
    ;;
  self-test)
    command -v jq >/dev/null 2>&1 || fail "jq is required"
    tmp="$(mktemp -d)"; trap 'rm -rf "$tmp"' EXIT
    probe_a=0123456789abcdef; probe_b=abcdef0123456789; sha=0123456789abcdef0123456789abcdef01234567
    jq -n --arg probe "$probe_a" --arg sha "$sha" '{schema_version:1,receipt_kind:"canary",canary:{probe_id:$probe,scenario:"failure"},source_event:"workflow_dispatch",source:{repository:"szTheory/sigra",ref:"refs/heads/main",sha:$sha},source_run:{id:"1001",attempt:1,workflow_id:10,workflow_name:"Release Receipt Canary",workflow_path:".github/workflows/release-receipt-canary.yml",url:"https://github.com/szTheory/sigra/actions/runs/1001",started_at:"2026-10-10T00:00:00Z",observed_at:"2026-10-10T00:01:00Z"},terminal_verdict:"failure",observer_run:null}' > "$tmp/failure-input.json"
    jq -n --arg probe "$probe_b" --arg sha "$sha" '{schema_version:1,receipt_kind:"canary",canary:{probe_id:$probe,scenario:"cancellation"},source_event:"workflow_dispatch",source:{repository:"szTheory/sigra",ref:"refs/heads/main",sha:$sha},source_run:{id:"1002",attempt:1,workflow_id:10,workflow_name:"Release Receipt Canary",workflow_path:".github/workflows/release-receipt-canary.yml",url:"https://github.com/szTheory/sigra/actions/runs/1002",started_at:"2026-10-10T00:00:00Z",observed_at:"2026-10-10T00:01:00Z"},terminal_verdict:"cancelled",observer_run:{id:"1003",attempt:1,workflow_id:11,url:"https://github.com/szTheory/sigra/actions/runs/1003",started_at:"2026-10-10T00:01:00Z",observed_at:"2026-10-10T00:02:00Z"}}' > "$tmp/cancellation-input.json"
    bash "$RECEIPT_HELPER" --mode canary --expected-workflow-id 10 --input "$tmp/failure-input.json" --output "$tmp/failure.json" >/dev/null
    bash "$RECEIPT_HELPER" --mode canary --expected-workflow-id 10 --input "$tmp/cancellation-input.json" --output "$tmp/cancellation.json" >/dev/null
    validate_receipt_pair "$tmp/failure.json" "$tmp/cancellation.json" || fail "local dual-outcome contract failed"
    if bash "$RECEIPT_HELPER" --input "$tmp/failure-input.json" --output "$tmp/production-rejected.json" >/dev/null 2>&1; then fail "production mode accepted a canary envelope"; fi
    echo "release-canary: self-test PASS"
    ;;
  validate-proof)
    [[ -n "$PROOF" && -f "$PROOF" ]] || fail "proof JSON file is required"
    jq -e 'def no_credential_keys:
      [.. | objects | to_entries[] |
        select((.key | test("(token|secret|credential|api.?key)";"i")) and
          (.key != "credential_values_recorded" or .value != false))] | length == 0;
      type == "object" and .schema_version == 1 and .status == "pass" and
      .credential_values_recorded == false and .preflight.status == "ready" and
      .preflight.credential_values_recorded == false and .source_failure.receipt.receipt_kind == "canary" and
      .source_failure.receipt.terminal_verdict == "failure" and .source_cancellation.receipt.receipt_kind == "canary" and
      .source_cancellation.receipt.terminal_verdict == "cancelled" and .source_failure.run_id != .source_cancellation.run_id and
      .source_failure.run_id == .source_failure.receipt.source_run_id and
      .source_cancellation.run_id == .source_cancellation.receipt.source_run_id and
      .source_failure.attempt == .source_failure.receipt.source_run_attempt and
      .source_cancellation.attempt == .source_cancellation.receipt.source_run_attempt and
      .source_failure.receipt.source_repository == "szTheory/sigra" and
      .source_cancellation.receipt.source_repository == "szTheory/sigra" and
      .source_failure.workflow_id == .source_failure.receipt.source_workflow_id and
      .source_cancellation.workflow_id == .source_cancellation.receipt.source_workflow_id and
      (.source_failure.workflow_path | sub("@main$";"")) == .source_failure.receipt.source_workflow_path and
      (.source_cancellation.workflow_path | sub("@main$";"")) == .source_cancellation.receipt.source_workflow_path and
      .source_failure.event == "workflow_dispatch" and .source_cancellation.event == "workflow_dispatch" and
      .source_failure.ref == "refs/heads/main" and .source_cancellation.ref == "refs/heads/main" and
      (.source_failure.sha | test("^[0-9a-f]{40}$")) and .source_failure.sha == .source_cancellation.sha and
      .source_cancellation.observer_run_id == .source_cancellation.receipt.observer_run.id and
      .source_cancellation.observer_workflow_path == ".github/workflows/release-run-observer.yml" and
      .source_cancellation.observer_event == "workflow_run" and .source_cancellation.observer_ref == "refs/heads/main" and
      .source_cancellation.observer_conclusion == "success" and
      (.source_failure.artifact.id | type == "number" and . > 0) and
      (.source_cancellation.artifact.id | type == "number" and . > 0) and
      (.source_failure.artifact.digest | test("^sha256:[0-9a-f]{64}$")) and
      (.source_cancellation.artifact.digest | test("^sha256:[0-9a-f]{64}$")) and
      .source_failure.artifact.name == ("release-canary-failure-" + .source_failure.run_id + "-" + (.source_failure.attempt|tostring) + "-" + .source_failure.receipt.probe_id) and
      .source_cancellation.artifact.name == ("release-canary-cancellation-" + .source_cancellation.run_id + "-" + (.source_cancellation.attempt|tostring)) and
      (.source_failure.artifact.expires_at | type == "string") and (.source_cancellation.artifact.expires_at | type == "string") and
      (.source_failure.created_at | type == "string") and (.source_failure.updated_at | type == "string") and
      (.source_cancellation.created_at | type == "string") and (.source_cancellation.updated_at | type == "string") and
      .retrieval.failure_zip_sha256 == (.source_failure.artifact.digest | sub("^sha256:";"")) and
      .retrieval.cancellation_zip_sha256 == (.source_cancellation.artifact.digest | sub("^sha256:";"")) and
      no_credential_keys' "$PROOF" >/dev/null || fail "proof is blocked, incomplete, misbound, or contains credential-shaped keys"
    # A saved JSON proof is not authoritative by itself. Re-query the exact
    # run and artifact records so changed conclusions, attempts, or artifact
    # bindings cannot be hidden by editing the captured file.
    verify_run_record() {
      local proof_path="$1" role="$2" record run_id live
      record=".${role}"
      run_id="$(jq -er "${record}.run_id | select(type == \"string\" and test(\"^[1-9][0-9]*$\"))" "$proof_path")" || return 1
      live="$(run_metadata "$run_id")" || return 1
      jq -e --argjson live "$live" --arg path "$record" '
        (getpath(($path|ltrimstr(".")|split(".")))) as $captured |
        ($live.id|tostring) == $captured.run_id and
        $live.run_attempt == $captured.attempt and
        ($live.workflow_id|tostring) == ($captured.workflow_id|tostring) and
        ($live.path|sub("@main$";"")) == ($captured.workflow_path|sub("@main$";"")) and
        $live.event == $captured.event and $live.head_branch == "main" and
        ("refs/heads/" + $live.head_branch) == $captured.ref and
        $live.head_sha == $captured.sha and $live.conclusion == $captured.conclusion and
        $live.created_at == $captured.created_at and $live.updated_at == $captured.updated_at
      ' "$proof_path" >/dev/null || return 1
      return 0
    }
    verify_artifact_record() {
      local proof_path="$1" record_path="$2" owner_id="$3" listing
      listing="$(gh api "repos/${REPOSITORY}/actions/runs/${owner_id}/artifacts")" || return 1
      jq -e --arg path "$record_path" --argjson owner "$owner_id" --argjson listing "$listing" '
        (getpath(($path|ltrimstr(".")|split(".")))) as $captured |
        [$listing.artifacts[]? | select(.id == $captured.id and .name == $captured.name and
          .expired == false and .workflow_run.id == $owner and .digest == $captured.digest and
          .expires_at == $captured.expires_at)] | length == 1
      ' "$proof_path" >/dev/null
    }
    verify_run_record "$PROOF" source_failure || fail "failure run no longer matches authoritative Actions metadata"
    verify_run_record "$PROOF" source_cancellation || fail "cancellation run no longer matches authoritative Actions metadata"
    observer_id="$(jq -er '.source_cancellation.observer_run_id | select(type == "string" and test("^[1-9][0-9]*$"))' "$PROOF")" || fail "observer run identity is malformed"
    observer_live="$(run_metadata "$observer_id")" || fail "observer run metadata is unavailable"
    jq -e --argjson live "$observer_live" '
      .source_cancellation as $c | $c.receipt.observer_run as $r |
      ($live.id|tostring) == $c.observer_run_id and
      $live.run_attempt == $c.observer_attempt and
      ($live.workflow_id|tostring) == ($c.observer_workflow_id|tostring) and
      ($live.path|sub("@main$";"")) == $c.observer_workflow_path and
      $live.event == $c.observer_event and $live.event == "workflow_run" and
      ("refs/heads/" + $live.head_branch) == $c.observer_ref and
      $live.head_branch == "main" and $live.conclusion == $c.observer_conclusion and
      ($r.id|tostring) == ($live.id|tostring) and $r.attempt == $live.run_attempt and
      ($r.workflow_id|tostring) == ($live.workflow_id|tostring)
    ' "$PROOF" >/dev/null || fail "observer run no longer matches authoritative Actions metadata"
    verify_artifact_record "$PROOF" .source_failure.artifact "$(jq -r '.source_failure.run_id' "$PROOF")" || fail "failure artifact no longer matches authoritative Actions metadata"
    verify_artifact_record "$PROOF" .source_cancellation.artifact "$observer_id" || fail "cancellation artifact no longer matches authoritative observer metadata"
    echo "release-canary: proof PASS"
    ;;
  write-failure) write_failure_receipt ;;
  preflight)
    run_preflight
    [[ "$(jq -r '.status' "$OUTPUT")" == ready ]] || exit 1
    ;;
  validate-preflight)
    [[ -n "$OUTPUT" ]] || fail "validated preflight output path is required"
    validate_committed_preflight "$OUTPUT" || fail "committed Actions preflight is not fresh or source-bound"
    echo "release-canary: preflight PASS"
    ;;
  prepare-preflight-input)
    prepare_preflight_input
    ;;
  run)
    [[ -n "$PROOF" ]] || fail "controller proof output path is required"
    run_controller
    ;;
  *) usage; exit 2 ;;
esac

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createHash, randomUUID } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const REF_PREFIX = 'refs/phase-249-preservation/';
const SHA = /^[0-9a-f]{40}$/;
const DIGEST = /^[0-9a-f]{64}$/;

function git(worktreePath, args, { env = process.env, input, encoding = 'buffer' } = {}) {
  return execFileSync('git', ['-C', worktreePath, ...args], {
    cwd: worktreePath,
    env,
    input,
    encoding,
    stdio: ['pipe', 'pipe', 'pipe'],
    maxBuffer: 64 * 1024 * 1024,
  });
}

function gitText(worktreePath, args, options = {}) {
  return git(worktreePath, args, { ...options, encoding: 'utf8' }).trimEnd();
}

function sha256(bytes) {
  return createHash('sha256').update(bytes).digest('hex');
}

function parseStatus(buffer) {
  const fields = buffer.toString('utf8').split('\0');
  const rows = [];
  for (let index = 0; index < fields.length; index += 1) {
    const value = fields[index];
    if (!value) continue;
    const status = value.slice(0, 2);
    const row = { status, path: value.slice(3), original_path: null };
    if (status.includes('R') || status.includes('C')) row.original_path = fields[++index] ?? null;
    rows.push(row);
  }
  return rows;
}

function inside(root, candidate) {
  const relative = path.relative(root, candidate);
  return relative === '' || (!relative.startsWith(`..${path.sep}`) && relative !== '..' && !path.isAbsolute(relative));
}

function assertSafeRelativePath(relativePath, root) {
  if (typeof relativePath !== 'string' || !relativePath || path.isAbsolute(relativePath) || relativePath.includes('\0')) {
    throw new Error('preservation path must be one non-empty worktree-relative path');
  }
  const absolutePath = path.resolve(root, relativePath);
  if (!inside(root, absolutePath)) throw new Error('preservation path escapes its source worktree');
  const parent = path.dirname(absolutePath);
  let realParent;
  try {
    realParent = fs.realpathSync(parent);
  } catch {
    throw new Error('preservation path parent cannot be read');
  }
  if (!inside(root, realParent)) throw new Error('preservation path resolves outside its source worktree');
  return absolutePath;
}

function sourceSnapshot(worktreePath, row) {
  const absolutePath = assertSafeRelativePath(row.path, worktreePath);
  let stat;
  let bytes = null;
  let contentState = 'deleted';
  try {
    stat = fs.lstatSync(absolutePath);
    if (stat.isSymbolicLink()) throw new Error('symlink preservation is unsupported; source path left untouched');
    if (!stat.isFile()) throw new Error('non-regular preservation path is unsupported; source path left untouched');
    bytes = fs.readFileSync(absolutePath);
    contentState = 'regular-file';
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
  }
  if (row.content_state && row.content_state !== contentState) {
    throw new Error(`source content state drift for ${row.path}`);
  }
  const digest = bytes === null ? null : sha256(bytes);
  if (row.sha256 !== digest) throw new Error(`source hash drift for ${row.path}`);
  return { absolutePath, bytes, stat, contentState, sha256: digest };
}

function scanSensitiveContent(bytes, relativePath) {
  if (!bytes) return;
  if (bytes.includes(0) || !Buffer.from(bytes.toString('utf8'), 'utf8').equals(bytes)) {
    throw new Error(`secret scan cannot safely inspect binary path ${relativePath}; source path left untouched`);
  }
  const text = bytes.toString('utf8');
  const checks = [
    ['private-key', /-----BEGIN (?:RSA |EC |OPENSSH |DSA )?PRIVATE KEY-----/],
    ['github-token', /\b(?:gh[pousr]_[A-Za-z0-9_]{20,}|github_pat_[A-Za-z0-9_]{20,})\b/],
    ['aws-access-key', /\bAKIA[0-9A-Z]{16}\b/],
    ['credential-assignment', /\b(?:secret_access_key|client_secret|access_token|api_key|private_key)\b\s*[:=]\s*["']?(?!<|\{\{|example|test|dummy|redacted)[A-Za-z0-9/+_=-]{24,}/i],
  ];
  for (const [rule, pattern] of checks) {
    if (pattern.test(text)) throw new Error(`secret-risk rule ${rule} matched ${relativePath}; source path left untouched`);
  }
}

function expectedStatusRow(worktreePath, expected) {
  const rows = parseStatus(git(worktreePath, ['status', '--porcelain=v1', '-z', '-uall']));
  const exact = rows.filter(row => row.path === expected.path);
  if (exact.length !== 1) throw new Error(`expected exactly one current status row for ${expected.path}`);
  const actual = exact[0];
  if (actual.status !== expected.status || (actual.original_path ?? null) !== (expected.original_path ?? null)) {
    throw new Error(`source status drift for ${expected.path}`);
  }
  return actual;
}

function classifyRow(row) {
  if (row.status === '??' && !row.original_path) return 'untracked';
  if (row.status === ' M' && !row.original_path) return 'modified';
  if (row.status === ' D' && !row.original_path) return 'deleted';
  throw new Error(`unsupported status ${JSON.stringify(row.status)} for ${row.path}; source path left untouched`);
}

function validateRef(ref) {
  if (typeof ref !== 'string' || !ref.startsWith(REF_PREFIX) || ref.includes('..') || !/^refs\/phase-249-preservation\/[A-Za-z0-9._/-]+$/.test(ref)) {
    throw new Error('preservation ref must be a safe refs/phase-249-preservation/* name');
  }
}

function tryResolveRef(worktreePath, ref) {
  try {
    return gitText(worktreePath, ['rev-parse', '--verify', `${ref}^{commit}`]);
  } catch {
    return null;
  }
}

function commitParent(worktreePath, commitSha) {
  const fields = gitText(worktreePath, ['rev-list', '--parents', '-n', '1', commitSha]).split(' ');
  return fields[1] ?? null;
}

function changedPaths(worktreePath, parentSha, commitSha) {
  return git(worktreePath, ['diff-tree', '--no-commit-id', '--name-only', '--no-renames', '-r', '-z', parentSha, commitSha])
    .toString('utf8').split('\0').filter(Boolean).sort();
}

function commitPathHash(worktreePath, commitSha, relativePath) {
  try {
    const bytes = git(worktreePath, ['show', `${commitSha}:${relativePath}`]);
    return sha256(bytes);
  } catch {
    return null;
  }
}

function existingRefMatches(worktreePath, refSha, sourceHead, row, kind, contentDigest) {
  if (commitParent(worktreePath, refSha) !== sourceHead) return false;
  const expectedChangedPaths = [row.path].sort();
  if (JSON.stringify(changedPaths(worktreePath, sourceHead, refSha)) !== JSON.stringify(expectedChangedPaths)) return false;
  if (kind === 'deleted') return commitPathHash(worktreePath, refSha, row.path) === null;
  return commitPathHash(worktreePath, refSha, row.path) === contentDigest;
}

function buildPreservationCommit(worktreePath, sourceHead, row, snapshot, kind, tempIndex) {
  const env = { ...process.env, GIT_INDEX_FILE: tempIndex };
  git(worktreePath, ['read-tree', sourceHead], { env });
  if (kind === 'deleted') {
    git(worktreePath, ['update-index', '--force-remove', '--', row.path], { env });
  } else {
    const blobSha = gitText(worktreePath, ['hash-object', '-w', '--stdin'], { input: snapshot.bytes });
    const mode = (snapshot.stat.mode & 0o111) === 0 ? '100644' : '100755';
    git(worktreePath, ['update-index', '--add', '--cacheinfo', mode, blobSha, row.path], { env });
  }
  const treeSha = gitText(worktreePath, ['write-tree'], { env });
  const message = [
    `Preserve Phase 249 path: ${row.path}`,
    '',
    `Source-Head: ${sourceHead}`,
    `Source-Status: ${row.status}`,
    `Content-SHA256: ${snapshot.sha256 ?? 'deleted'}`,
  ].join('\n');
  return gitText(worktreePath, ['commit-tree', treeSha, '-p', sourceHead, '-F', '-'], { input: Buffer.from(message) });
}

function verifyPinnedObject(worktreePath, ref, objectSha, sourceHead, row, kind, snapshot) {
  const resolved = gitText(worktreePath, ['rev-parse', '--verify', `${ref}^{commit}`]);
  if (resolved !== objectSha) throw new Error(`pinned preservation ref changed before read-back: ${ref}`);
  if (commitParent(worktreePath, resolved) !== sourceHead) throw new Error(`preservation ref ${ref} has an unexpected source parent`);
  if (JSON.stringify(changedPaths(worktreePath, sourceHead, resolved)) !== JSON.stringify([row.path])) {
    throw new Error(`preservation ref ${ref} does not contain the exact path set`);
  }
  if (kind === 'deleted') {
    if (commitPathHash(worktreePath, resolved, row.path) !== null) throw new Error(`preservation ref ${ref} did not preserve the deletion`);
    if (!commitPathHash(worktreePath, sourceHead, row.path)) throw new Error(`deleted source ${row.path} cannot be reconstructed from its parent`);
  } else if (commitPathHash(worktreePath, resolved, row.path) !== snapshot.sha256) {
    throw new Error(`preservation ref ${ref} cannot recover exact bytes for ${row.path}`);
  }
}

function cleanExactSourcePath(worktreePath, row, kind, snapshot) {
  expectedStatusRow(worktreePath, row);
  const fresh = sourceSnapshot(worktreePath, row);
  if (fresh.sha256 !== snapshot.sha256) throw new Error(`source hash changed immediately before cleanup for ${row.path}`);
  if (kind === 'untracked') {
    fs.unlinkSync(fresh.absolutePath);
  } else {
    git(worktreePath, ['restore', '--worktree', '--source=HEAD', '--', row.path]);
  }
  const remaining = parseStatus(git(worktreePath, ['status', '--porcelain=v1', '-z', '-uall']))
    .filter(value => value.path === row.path || value.original_path === row.path);
  if (remaining.length > 0) throw new Error(`source path ${row.path} remains dirty after exact cleanup`);
}

/**
 * Pin one source path under a compare-and-swap ref, read the object back, and
 * only then clean that same path in its original worktree.
 */
export function preservePath({
  repoRoot,
  worktreePath,
  row,
  expectedHead,
  owner,
  target,
  action,
  reason,
  source: sourceRecord,
  ref,
}) {
  if (![owner, target, action, reason, sourceRecord].every(value => typeof value === 'string' && value.trim())) {
    throw new Error('preservation requires explicit owner, target, action, reason, and source');
  }
  if (!row || typeof row.path !== 'string' || typeof row.status !== 'string') throw new Error('one exact ledger path/status row is required');
  validateRef(ref);

  const actualRoot = path.resolve(gitText(worktreePath, ['rev-parse', '--show-toplevel']));
  const suppliedRoot = fs.realpathSync(worktreePath);
  if (actualRoot !== suppliedRoot) throw new Error('source worktree path does not resolve to its Git root');
  worktreePath = actualRoot;
  const sourceHead = gitText(worktreePath, ['rev-parse', 'HEAD']);
  if (!SHA.test(sourceHead)) throw new Error('source HEAD is not a full commit identity');
  if (!SHA.test(expectedHead ?? '') || sourceHead !== expectedHead) throw new Error(`source HEAD drift for ${row.path}`);
  if (repoRoot) {
    const commonDir = directory => {
      const value = gitText(directory, ['rev-parse', '--git-common-dir']);
      return fs.realpathSync(path.resolve(directory, value));
    };
    if (commonDir(repoRoot) !== commonDir(worktreePath)) throw new Error('source worktree belongs to a different Git object/ref store');
  }
  expectedStatusRow(worktreePath, row);
  const kind = classifyRow(row);
  if (row.status !== '??' && row.status[0] !== ' ') throw new Error(`staged or conflicted status is unsupported for ${row.path}`);
  const indexBefore = gitText(worktreePath, ['write-tree']);
  const snapshot = sourceSnapshot(worktreePath, row);
  if (kind === 'deleted' && snapshot.contentState !== 'deleted') throw new Error(`deleted source path ${row.path} unexpectedly exists`);
  if (kind !== 'deleted' && snapshot.contentState !== 'regular-file') throw new Error(`source path ${row.path} is not a regular file`);
  scanSensitiveContent(snapshot.bytes, row.path);

  const oldObject = tryResolveRef(worktreePath, ref);
  let objectSha;
  let created = false;
  const tempIndex = path.join(os.tmpdir(), `phase-249-preservation-${process.pid}-${randomUUID()}.index`);
  try {
    if (oldObject) {
      if (!existingRefMatches(worktreePath, oldObject, sourceHead, row, kind, snapshot.sha256)) {
        throw new Error(`preservation ref collision at ${ref}; existing bytes differ and remain recoverable`);
      }
      objectSha = oldObject;
    } else {
      objectSha = buildPreservationCommit(worktreePath, sourceHead, row, snapshot, kind, tempIndex);
      const zero = '0'.repeat(40);
      try {
        git(worktreePath, ['update-ref', ref, objectSha, zero]);
        created = true;
      } catch {
        const racedObject = tryResolveRef(worktreePath, ref);
        if (!racedObject || !existingRefMatches(worktreePath, racedObject, sourceHead, row, kind, snapshot.sha256)) {
          throw new Error(`preservation ref compare-and-swap collision at ${ref}; source path left untouched`);
        }
        objectSha = racedObject;
      }
    }

    verifyPinnedObject(worktreePath, ref, objectSha, sourceHead, row, kind, snapshot);
    expectedStatusRow(worktreePath, row);
    const second = sourceSnapshot(worktreePath, row);
    if (second.sha256 !== snapshot.sha256 || gitText(worktreePath, ['rev-parse', 'HEAD']) !== sourceHead) {
      throw new Error(`source changed after ref verification for ${row.path}; source path left untouched`);
    }
    if (gitText(worktreePath, ['write-tree']) !== indexBefore) throw new Error('source index changed during preservation; source path left untouched');

    cleanExactSourcePath(worktreePath, row, kind, snapshot);
    if (gitText(worktreePath, ['rev-parse', 'HEAD']) !== sourceHead) throw new Error('source branch HEAD changed during exact cleanup');
    if (gitText(worktreePath, ['write-tree']) !== indexBefore) throw new Error('source index changed during exact cleanup');

    return {
      schema_version: 1,
      state: 'preserved',
      owner,
      target,
      action,
      reason,
      source_record: sourceRecord,
      worktree_path: actualRoot,
      source_head_sha: sourceHead,
      source_status: row.status,
      source_path: row.path,
      source_content_state: snapshot.contentState,
      source_sha256: snapshot.sha256,
      ref,
      object_sha: objectSha,
      ref_created: created,
      paths: [{ path: row.path, status: row.status, content_state: snapshot.contentState, sha256: snapshot.sha256 }],
      source_clean_after_readback: true,
      source_head_unchanged: true,
      source_index_unchanged: true,
    };
  } finally {
    for (const suffix of ['', '.lock']) {
      try { fs.unlinkSync(`${tempIndex}${suffix}`); } catch (error) { if (error.code !== 'ENOENT') throw error; }
    }
  }
}

function parseArgs(args) {
  const values = {};
  for (let index = 0; index < args.length; index += 1) {
    const key = args[index];
    if (!key.startsWith('--') || index + 1 >= args.length) throw new Error(`invalid argument near ${key}`);
    values[key.slice(2)] = args[++index];
  }
  return values;
}

function cliRef(worktreePath, relativePath) {
  const key = sha256(Buffer.from(`${path.resolve(worktreePath)}\0${relativePath}`)).slice(0, 32);
  return `${REF_PREFIX}${key}`;
}

async function main() {
  const values = parseArgs(process.argv.slice(2));
  for (const name of ['ledger', 'worktree', 'path', 'owner', 'target', 'action', 'reason', 'source']) {
    if (!values[name]) throw new Error(`--${name} is required`);
  }
  const ledgerPath = path.resolve(values.ledger);
  const ledger = JSON.parse(fs.readFileSync(ledgerPath, 'utf8'));
  const worktree = (ledger.worktrees ?? []).find(row => path.resolve(row.path) === fs.realpathSync(values.worktree));
  if (!worktree) throw new Error(`worktree is not registered in ${ledgerPath}`);
  const row = (worktree.inherited_dirty_paths ?? worktree.dirty_paths ?? []).find(value => value.path === values.path);
  if (!row) throw new Error(`exact path ${values.path} is absent from the ledger for ${worktree.path}`);
  const ref = values.ref ?? cliRef(values.worktree, row.path);
  const proof = preservePath({
    repoRoot: values.repoRoot ?? ledger.evidence_artifacts?.worktree_path ?? process.cwd(),
    worktreePath: worktree.path,
    expectedHead: worktree.head_sha,
    row,
    owner: values.owner,
    target: values.target,
    action: values.action,
    reason: values.reason,
    source: values.source,
    ref,
  });
  process.stdout.write(`${JSON.stringify(proof, null, 2)}\n`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main().catch(error => {
    process.stderr.write(`preserve-phase-249-worktrees: ${error.message}\n`);
    process.exitCode = 1;
  });
}

import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';

import { preservePath } from './preserve-phase-249-worktrees.mjs';

function fixture(t) {
  const repo = fs.mkdtempSync(path.join(os.tmpdir(), 'sigra-phase-249-preserve-'));
  t.after(() => fs.rmSync(repo, { recursive: true, force: true }));
  const git = (...args) => execFileSync('git', args, { cwd: repo, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trim();
  const status = relativePath => execFileSync('git', ['status', '--porcelain=v1', '--', relativePath], { cwd: repo, encoding: 'utf8' }).replace(/\n$/, '');
  git('init', '-q', '--initial-branch=main');
  git('config', 'user.name', 'Phase 249 Fixture');
  git('config', 'user.email', 'phase-249-fixture@example.invalid');
  fs.mkdirSync(path.join(repo, 'notes'));
  fs.writeFileSync(path.join(repo, 'notes/change.md'), 'baseline\n');
  fs.writeFileSync(path.join(repo, 'anchor.txt'), 'anchor\n');
  git('add', 'notes/change.md', 'anchor.txt');
  git('commit', '-m', 'fixture baseline');
  return { repo, git, status };
}

function digest(bytes) {
  return createHash('sha256').update(bytes).digest('hex');
}

function preservationRow(repo, contents = Buffer.from('inherited change\n')) {
  const relativePath = 'notes/change.md';
  fs.writeFileSync(path.join(repo, relativePath), contents);
  return {
    path: relativePath,
    status: ' M',
    content_state: 'regular-file',
    sha256: digest(contents),
  };
}

const details = ref => ({
  owner: 'Phase 249 preservation fixture',
  target: ref,
  action: 'Pin the exact path under a local preservation ref, verify it, then clean only that path.',
  reason: 'The fixture verifies recoverability before source cleanup.',
  source: 'Disposable Git worktree fixture with exact status and SHA-256 captured before the call.',
});

test('pins and reads back exact bytes before cleaning only the selected tracked path', t => {
  const { repo, git, status } = fixture(t);
  const row = preservationRow(repo);
  const expectedHead = git('rev-parse', 'HEAD');
  const expectedBranch = git('branch', '--show-current');
  const expectedIndexTree = git('write-tree');
  fs.writeFileSync(path.join(repo, 'notes/leave-alone.md'), 'another inherited path\n');
  const ref = 'refs/phase-249-preservation/fixture-tracked';

  const proof = preservePath({
    repoRoot: repo,
    worktreePath: repo,
    row,
    expectedHead,
    ...details(ref),
    ref,
  });

  assert.equal(proof.state, 'preserved');
  assert.equal(proof.source_head_sha, expectedHead);
  assert.equal(proof.ref, ref);
  assert.equal(git('rev-parse', `${ref}^{commit}`), proof.object_sha);
  assert.equal(git('show', `${ref}:notes/change.md`), 'inherited change');
  assert.equal(status('notes/change.md'), '');
  assert.equal(status('notes/leave-alone.md'), '?? notes/leave-alone.md');
  assert.equal(git('rev-parse', 'HEAD'), expectedHead);
  assert.equal(git('branch', '--show-current'), expectedBranch);
  assert.equal(git('write-tree'), expectedIndexTree);
  assert.deepEqual(proof.paths, [{
    path: 'notes/change.md',
    status: ' M',
    content_state: 'regular-file',
    sha256: row.sha256,
  }]);
});

test('hash drift blocks before a ref is written or the source path is changed', t => {
  const { repo, git, status } = fixture(t);
  const row = preservationRow(repo);
  const pathOnDisk = path.join(repo, row.path);
  fs.writeFileSync(pathOnDisk, 'concurrent replacement\n');
  const before = fs.readFileSync(pathOnDisk);
  const ref = 'refs/phase-249-preservation/fixture-hash-drift';

  assert.throws(() => preservePath({ repoRoot: repo, worktreePath: repo, row, expectedHead: git('rev-parse', 'HEAD'), ...details(ref), ref }), /hash|drift/i);

  assert.deepEqual(fs.readFileSync(pathOnDisk), before);
  assert.throws(() => git('rev-parse', '--verify', ref));
  assert.equal(status(row.path), ' M notes/change.md');
});

test('an existing ref with different recovered bytes blocks without overwriting either source or ref', t => {
  const { repo, git, status } = fixture(t);
  const base = git('rev-parse', 'HEAD');
  fs.writeFileSync(path.join(repo, 'notes/change.md'), 'different ref bytes\n');
  git('add', 'notes/change.md');
  git('commit', '-m', 'existing preservation object');
  const existing = git('rev-parse', 'HEAD');
  const ref = 'refs/phase-249-preservation/fixture-collision';
  git('update-ref', ref, existing);
  git('reset', '--hard', base);
  const row = preservationRow(repo, Buffer.from('new source bytes\n'));
  const sourceBytes = fs.readFileSync(path.join(repo, row.path));

  assert.throws(() => preservePath({ repoRoot: repo, worktreePath: repo, row, expectedHead: base, ...details(ref), ref }), /ref.*collision|collision/i);

  assert.deepEqual(fs.readFileSync(path.join(repo, row.path)), sourceBytes);
  assert.equal(git('rev-parse', `${ref}^{commit}`), existing);
  assert.equal(git('show', `${ref}:notes/change.md`), 'different ref bytes');
  assert.equal(status(row.path), ' M notes/change.md');
});

#!/usr/bin/env node

import { createHash } from "node:crypto";
import { readFileSync, writeFileSync, renameSync, readdirSync, realpathSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";

const SCRIPT_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const PHASE_DIR = ".planning/phases/245-branch-prune-local-and-remote";
const GIT_BIN = "/usr/bin/git";
const GIT_VERSION_PREFIX = "git version 2.50.1";
const GIT_SHA256 = "b8763cf250e607a778bb4603cecb5b90338814d0a3dfcba0d57b1de242f610e9";
const OID = /^[0-9a-f]{40}(?:[0-9a-f]{24})?$/;
const TYPES = new Set(["commit", "tree", "blob", "tag"]);
const SHELL_MUTATOR_PATHS = [
  "scripts/maintainers/prune-stale-branches.sh",
  "scripts/maintainers/repo-mutation-coordinator.sh",
  "scripts/maintainers/repo-mutation-reference-transaction",
];
const PINNED_RUNTIME_PATHS = [
  "scripts/maintainers/prune-stale-branches-admission.mjs",
  "scripts/maintainers/prune-stale-branches-current.mjs",
  "scripts/maintainers/prune-stale-branches-readiness.mjs",
  "scripts/maintainers/prune-stale-branches-pr-audit.mjs",
];
const EXECUTABLES = new Set(["spawn", "spawnSync", "execFile", "execFileSync", "execSync", "command"]);

function fail(code, detail = "") {
  throw new Error(detail ? `${code}:${detail}` : code);
}

function command(program, args, { cwd, input, encoding = "utf8", maxBuffer = 32 * 1024 * 1024 } = {}) {
  const result = spawnSync(program, args, { cwd, input, encoding, maxBuffer });
  if (result.error || result.status !== 0) {
    const message = (result.stderr || result.stdout || result.error?.message || "").toString().trim();
    fail("command_failed", `${program} ${args.join(" ")}: ${message}`);
  }
  return result.stdout;
}

function git(repo, args, options = {}) {
  return command(GIT_BIN, ["-C", repo, ...args], options);
}

function sourceFiles(root, directory = "scripts") {
  const base = path.join(root, directory);
  if (!base.startsWith(`${root}${path.sep}`) || !path.isAbsolute(root)) return [];
  let entries;
  try { entries = readdirSync(base, { withFileTypes: true }); } catch { return []; }
  return entries.flatMap((entry) => {
    if (entry.name === "node_modules" || entry.name.startsWith(".")) return [];
    const relative = path.join(directory, entry.name);
    if (entry.isDirectory()) return sourceFiles(root, relative);
    if (!entry.isFile() || /\.test\.[^.]+$/.test(entry.name)) return [];
    if (!/\.(?:sh|bash|mjs|js)$/.test(entry.name) && entry.name !== "repo-mutation-reference-transaction") return [];
    return [relative];
  });
}

function stripShellComment(line) {
  let quote = "";
  let escaped = false;
  for (let index = 0; index < line.length; index += 1) {
    const char = line[index];
    if (escaped) { escaped = false; continue; }
    if (quote === "'" && char !== "'") continue;
    if (quote === '"' && char !== '"' && char !== "\\") continue;
    if (char === "\\" && quote !== "'") { escaped = true; continue; }
    if ((char === "'" || char === '"') && (!quote || quote === char)) { quote = quote ? "" : char; continue; }
    if (!quote && char === "#") return line.slice(0, index);
  }
  return line;
}

function shellMutatorSites(source) {
  const mutation = /\b(?:update-ref|branch\s+-[dD]|worktree\s+(?:add|move|remove|prune|lock|unlock)|checkout\s+-[bB]|switch\s+-[cC])\b/;
  return source.split(/\r?\n/).flatMap((line, index) => {
    const code = stripShellComment(line);
    return /\bgit\b/.test(code) && mutation.test(code) ? [{ line: index + 1, source: line }] : [];
  });
}

function shellUsesPinnedGitFunction(line) {
  const code = stripShellComment(line);
  if (/(['"])?\/(?:[^\s/'"]+\/)*git\1?\s/.test(code)) return false;
  if (/(?:^|[;&|()\s])(?:command|env|exec|nohup|sudo)\s+(?:[^\s;&|()]+\s+)*git\s/.test(code)) return false;
  return /(?:^|[;&|()\s])git\s/.test(code);
}

function jsTokens(source) {
  const tokens = [];
  let index = 0;
  let previous = "";
  while (index < source.length) {
    const char = source[index];
    if (/\s/.test(char)) { index += 1; continue; }
    if (char === "/" && source[index + 1] === "/") {
      index = source.indexOf("\n", index + 2);
      if (index < 0) break;
      continue;
    }
    if (char === "/" && source[index + 1] === "*") {
      const end = source.indexOf("*/", index + 2);
      index = end < 0 ? source.length : end + 2;
      continue;
    }
    if (char === "/" && /^(?:=|\(|\[|\{|:|,|;|!|\?|&&|\|\||return|throw)$/.test(previous)) {
      index += 1;
      let escaped = false;
      while (index < source.length) {
        const current = source[index++];
        if (escaped) { escaped = false; continue; }
        if (current === "\\") { escaped = true; continue; }
        if (current === "/") break;
        if (current === "\n") break;
      }
      while (/[a-z]/i.test(source[index] ?? "")) index += 1;
      previous = "<regex>";
      continue;
    }
    if (char === "'" || char === '"' || char === "`") {
      const quote = char;
      let value = "";
      index += 1;
      let escaped = false;
      while (index < source.length) {
        const current = source[index++];
        if (escaped) { value += current; escaped = false; continue; }
        if (current === "\\") { escaped = true; continue; }
        if (current === quote) break;
        value += current;
      }
      tokens.push({ type: quote === "`" ? "template" : "string", value });
      previous = "<literal>";
      continue;
    }
    if (/[A-Za-z_$]/.test(char)) {
      const start = index++;
      while (/[A-Za-z0-9_$]/.test(source[index] ?? "")) index += 1;
      const value = source.slice(start, index);
      tokens.push({ type: "identifier", value });
      previous = value;
      continue;
    }
    tokens.push({ type: "punctuation", value: char });
    previous = char;
    index += 1;
  }
  return tokens;
}

function unpinnedJsGitCalls(source) {
  const tokens = jsTokens(source);
  const calls = [];
  for (let index = 0; index < tokens.length - 2; index += 1) {
    if (tokens[index].type !== "identifier" || !EXECUTABLES.has(tokens[index].value)) continue;
    if (tokens[index + 1].value !== "(" || tokens[index + 2].type !== "string" || tokens[index + 2].value !== "git") continue;
    calls.push(`${tokens[index].value}("git", ...)`);
  }
  return calls;
}

export function inspectMutationCoverage(root) {
  const absoluteRoot = path.resolve(root);
  const files = sourceFiles(absoluteRoot);
  const fileSet = new Set(files);
  const findings = [];
  const coordinatorPath = "scripts/maintainers/repo-mutation-coordinator.sh";
  const operatorPath = "scripts/maintainers/prune-stale-branches.sh";
  const coordinator = fileSet.has(coordinatorPath) ? readFileSync(path.join(absoluteRoot, coordinatorPath), "utf8") : "";
  const operator = fileSet.has(operatorPath) ? readFileSync(path.join(absoluteRoot, operatorPath), "utf8") : "";
  const coordinatorPinned = coordinator.includes('readonly SIGRA_COORDINATOR_GIT_PATH="/usr/bin/git"')
    && coordinator.includes(`readonly SIGRA_COORDINATOR_GIT_SHA256="${GIT_SHA256}"`)
    && coordinator.includes('"$SIGRA_COORDINATOR_GIT_PATH" "$@"')
    && coordinator.includes("sigra_coordinator_pin_git || return 126");
  if (!coordinatorPinned) findings.push(`${coordinatorPath}: pinned_git_wrapper_missing_or_changed`);
  const operatorPinned = operator.includes('source "${SCRIPT_ROOT}/scripts/maintainers/repo-mutation-coordinator.sh"')
    && operator.includes('sigra_coordinator_pin_git || fail')
    && operator.includes('sigra_coordinator_acquire "$REPO"')
    && operator.includes(') acquire_lock ;;');
  if (!operatorPinned) {
    findings.push(`${operatorPath}: shared_pinned_git_wrapper_not_sourced`);
  }
  for (const relativePath of PINNED_RUNTIME_PATHS) {
    if (!fileSet.has(relativePath)) { findings.push(`${relativePath}: runtime_entrypoint_missing`); continue; }
    const source = readFileSync(path.join(absoluteRoot, relativePath), "utf8");
    if (!source.includes(`const GIT_BIN = "${GIT_BIN}";`)) findings.push(`${relativePath}: exact_git_path_pin_missing`);
    for (const call of unpinnedJsGitCalls(source)) findings.push(`${relativePath}: ${call}`);
  }
  for (const relativePath of files) {
    if (!/\.(?:sh|bash)$/.test(relativePath) && relativePath !== "scripts/maintainers/repo-mutation-reference-transaction") continue;
    const source = readFileSync(path.join(absoluteRoot, relativePath), "utf8");
    for (const site of shellMutatorSites(source)) {
      const disposableProbe = relativePath === coordinatorPath && site.source.includes("DISPOSABLE_PROBE_MUTATION");
      const coveredOperatorSite = relativePath === operatorPath && coordinatorPinned && operatorPinned
        && shellUsesPinnedGitFunction(site.source);
      const coveredCoordinatorSite = relativePath === coordinatorPath && coordinatorPinned && disposableProbe;
      if (!coveredOperatorSite && !coveredCoordinatorSite) findings.push(`${relativePath}:${site.line}: uncoordinated Git ref/worktree mutator`);
    }
    if ((relativePath === operatorPath || relativePath === coordinatorPath) && /\bcommand\s+-v\s+git\b/.test(source)) {
      findings.push(`${relativePath}: ambient_git_path_lookup`);
    }
  }
  for (const relativePath of SHELL_MUTATOR_PATHS) {
    if (!fileSet.has(relativePath)) findings.push(`${relativePath}: mutation_entrypoint_missing`);
  }
  return [...new Set(findings)];
}

function safePath(value) {
  if (typeof value !== "string" || !value || value.startsWith("/") || value.includes("..") || value.includes("\n") || value.includes(":")) {
    fail("input_path_invalid", value ?? "");
  }
  return value;
}

function readPinned(repo, commit, relativePath, label) {
  safePath(relativePath);
  if (!OID.test(commit ?? "")) fail(`${label}_commit_invalid`);
  try { git(repo, ["cat-file", "-e", `${commit}^{commit}`]); } catch { fail(`${label}_commit_unavailable`, commit); }
  let blob;
  try { blob = git(repo, ["rev-parse", `${commit}:${relativePath}`]).trim(); } catch { fail(`${label}_path_unavailable`, relativePath); }
  const raw = command(GIT_BIN, ["-C", repo, "show", `${commit}:${relativePath}`], { encoding: null });
  const recalculated = command(GIT_BIN, ["-C", repo, "hash-object", "--stdin", "-t", "blob"], { input: raw }).trim();
  if (blob !== recalculated) fail(`${label}_blob_mismatch`, relativePath);
  return { raw, blob, sha256: createHash("sha256").update(raw).digest("hex") };
}

function refsFingerprint(repo) {
  return git(repo, ["for-each-ref", "--format=%(refname)%09%(objectname)%09%(objecttype)%09%(*objectname)%09%(*objecttype)%09%(symref)"])
    .trimEnd().split(/\r?\n/).filter(Boolean).sort();
}

function worktreeFingerprint(repo) {
  const rows = git(repo, ["worktree", "list", "--porcelain"]).trimEnd();
  return rows ? rows.split(/\r?\n/).filter(Boolean) : [];
}

function configFingerprint(repo) {
  let bytes;
  try { bytes = git(repo, ["config", "--local", "--list", "--null"], { encoding: null }); }
  catch { bytes = Buffer.alloc(0); }
  return createHash("sha256").update(bytes).digest("hex");
}

function committedInputSet(options) {
  const specs = [
    ["current_contract", options.currentContractCommit, options.currentContract],
    ["local_snapshot", options.snapshotCommit, options.snapshot],
    ["origin_snapshot", options.originSnapshotCommit, options.originSnapshot],
    ["allowlist", options.allowlistCommit, options.allowlist],
    ["readiness", options.readinessCommit, options.readiness],
  ];
  if (options.admission) specs.push(["initial_admission", options.currentContractCommit, options.admission]);
  const inputs = {};
  for (const [name, commit, file] of specs) {
    if (!commit || !file) fail(`${name}_commit_path_required`);
    inputs[name] = { commit, path: safePath(file), ...readPinned(options.repo, commit, file, name) };
  }
  return inputs;
}

function parseAllowlist(bytes) {
  const lines = bytes.toString("utf8").replace(/\r/g, "").trimEnd().split("\n");
  if (lines.length < 2 || lines[0] !== "side\tref\toid\ttype\treason") fail("allowlist_header_invalid");
  const rows = [];
  const seen = new Set();
  for (const line of lines.slice(1)) {
    const [side, ref, oid, type, reason, ...extra] = line.split("\t");
    if (extra.length || !["local", "remote", "tracking", "safety-publish"].includes(side) || !ref?.startsWith("refs/") || !OID.test(oid ?? "") || !TYPES.has(type) || !reason?.trim()) fail("allowlist_row_invalid");
    if (seen.has(`${side}\0${ref}`)) fail("allowlist_duplicate_row", ref);
    if (command(GIT_BIN, ["check-ref-format", ref]).trim() !== "") fail("allowlist_ref_invalid", ref);
    seen.add(`${side}\0${ref}`);
    rows.push({ side, ref, oid, type, reason });
  }
  if (!rows.length) fail("allowlist_empty");
  return rows;
}

function checkReadiness(repo, input, reasons) {
  let receipt;
  try { receipt = JSON.parse(input.raw.toString("utf8")); } catch { fail("readiness_json_invalid"); }
  if (receipt?.status !== "ready") reasons.push({ code: "d01_readiness_not_ready" });
  const source = receipt?.source_commit;
  if (!OID.test(source ?? "")) reasons.push({ code: "d01_readiness_source_commit_invalid" });
  else {
    const resolved = spawnSync(GIT_BIN, ["-C", repo, "rev-parse", "--verify", `${source}^{commit}`], { encoding: "utf8" });
    if (resolved.status !== 0 || resolved.stdout.trim() !== source) {
      reasons.push({ code: `d01_readiness_source_commit_unavailable:${source}` });
    } else {
      const verified = spawnSync("node", [path.join(SCRIPT_ROOT, "scripts/maintainers/prune-stale-branches-readiness.mjs"), "verify", "--repo", repo, "--artifact", input.path, "--artifact-commit", input.commit], { encoding: "utf8" });
      if (verified.status !== 0) reasons.push({ code: `d01_readiness_source_verification_failed:${(verified.stderr || verified.stdout).trim().slice(0, 240)}` });
    }
  }
}

function checkRuntime(reasons) {
  const resolved = spawnSync("sh", ["-lc", "command -v git"], { encoding: "utf8" });
  const ambientGitPath = resolved.status === 0 ? resolved.stdout.trim() : null;
  let candidate = null;
  let pinnedGitVerified = false;
  try {
    const resolvedPath = realpathSync(GIT_BIN);
    const digest = createHash("sha256").update(readFileSync(GIT_BIN)).digest("hex");
    const version = command(GIT_BIN, ["--version"]).trim();
    pinnedGitVerified = resolvedPath === GIT_BIN && version.startsWith(GIT_VERSION_PREFIX) && digest === GIT_SHA256;
    candidate = { path: GIT_BIN, resolved_path: resolvedPath, version, sha256: digest };
  } catch {
    candidate = null;
  }
  if (!pinnedGitVerified) reasons.push({ code: "pinned_git_identity_unverified" });
  const coverageFindings = inspectMutationCoverage(SCRIPT_ROOT);
  if (coverageFindings.length) reasons.push({ code: "mutator_coverage_failed", findings: coverageFindings });
  return {
    active_git_path: ambientGitPath,
    candidate_git: candidate,
    pinned_git_verified: pinnedGitVerified,
    operator_mutators_pinned: pinnedGitVerified && coverageFindings.length === 0,
    mutator_coverage: { status: coverageFindings.length ? "blocked" : "passed", findings: coverageFindings },
  };
}

function checkCoordinator(repo, stage, reasons) {
  if (stage === "admission") return { stage, installed: false, checked: false };
  const verify = spawnSync("bash", [path.join(SCRIPT_ROOT, "scripts/maintainers/repo-mutation-coordinator.sh"), "verify", "--repo", repo], { encoding: "utf8" });
  const held = process.env.SIGRA_BRANCH_WORKTREE_COORDINATOR_TOKEN && process.env.SIGRA_COORDINATOR_HELD === "1";
  if (verify.status !== 0 || !held) reasons.push({ code: `coordinator_not_proven_under_lock:${(verify.stderr || verify.stdout).trim().slice(0, 240)}` });
  return { stage, installed: verify.status === 0, held: Boolean(held) };
}

function checkCandidate(repo, rows, candidateRef, reasons) {
  if (!candidateRef) fail("candidate_ref_required");
  const candidate = rows.find((row) => row.side === "local" && row.ref === candidateRef);
  if (!candidate) {
    reasons.push({ code: `candidate_not_in_exact_allowlist:${candidateRef}` });
    return null;
  }
  const actual = spawnSync(GIT_BIN, ["-C", repo, "for-each-ref", `--format=%(objectname)%09%(objecttype)`, candidateRef], { encoding: "utf8" });
  if (actual.status !== 0 || actual.stdout.trim() !== `${candidate.oid}\t${candidate.type}`) reasons.push({ code: `candidate_identity_changed:${candidateRef}` });
  if (candidate.type !== "commit") reasons.push({ code: `candidate_not_commit:${candidateRef}` });
  const worktrees = worktreeFingerprint(repo);
  if (worktrees.some((line) => line === `branch ${candidateRef}`)) reasons.push({ code: `candidate_attached_worktree:${candidateRef}` });
  const head = spawnSync(GIT_BIN, ["-C", repo, "symbolic-ref", "-q", "HEAD"], { encoding: "utf8" });
  const target = head.status === 0 ? head.stdout.trim() : null;
  const targetOid = target ? git(repo, ["rev-parse", "--verify", target]).trim() : null;
  if (!target || !target.startsWith("refs/heads/") || !targetOid) reasons.push({ code: "merge_target_not_stable_symbolic_branch" });
  else {
    const ancestor = spawnSync(GIT_BIN, ["-C", repo, "merge-base", "--is-ancestor", candidate.oid, targetOid]);
    if (ancestor.status !== 0) reasons.push({ code: `candidate_not_merged_into_stable_target:${candidateRef}` });
  }
  return candidate;
}

function evaluate(options) {
  const repo = path.resolve(options.repo);
  const root = git(repo, ["rev-parse", "--show-toplevel"]).trim();
  const before = { refs: refsFingerprint(root), worktrees: worktreeFingerprint(root), config: configFingerprint(root) };
  const reasons = [];
  const inputs = committedInputSet({ ...options, repo: root });
  const contract = JSON.parse(inputs.current_contract.raw.toString("utf8"));
  if (contract?.schema_version !== 1) reasons.push({ code: "current_contract_schema_invalid" });
  const allowRows = parseAllowlist(inputs.allowlist.raw);
  const allowPin = (contract?.pinned_inputs ?? []).find((row) => row.commit === inputs.allowlist.commit && row.path === inputs.allowlist.path)
    ?? (inputs.allowlist.commit === inputs.current_contract.commit ? contract?.evidence_transition?.precommit_artifacts?.[inputs.allowlist.path] : null);
  if (!allowPin || allowPin.blob !== inputs.allowlist.blob || allowPin.sha256 !== inputs.allowlist.sha256) reasons.push({ code: "allowlist_not_pinned_by_current_contract" });
  if (inputs.initial_admission) {
    const receipt = JSON.parse(inputs.initial_admission.raw.toString("utf8"));
    const receiptPin = contract?.evidence_transition?.precommit_artifacts?.[inputs.initial_admission.path];
    if (!receiptPin || receiptPin.blob !== inputs.initial_admission.blob || receiptPin.sha256 !== inputs.initial_admission.sha256) {
      reasons.push({ code: "initial_admission_not_pinned_by_current_contract" });
    }
    if (receipt?.schema_version !== 1 || receipt?.status !== "prepared" || receipt?.production_mutations !== 0) {
      reasons.push({ code: "initial_admission_receipt_invalid_or_not_read_only" });
    }
  }

  // Readiness is the earliest production gate. In particular, do not contact
  // GitHub or inspect coordinator state after the pinned D-01 source is known
  // to be absent: the operator must fail before any mutation setup begins.
  checkReadiness(root, inputs.readiness, reasons);

  const currentArgs = [path.join(SCRIPT_ROOT, "scripts/maintainers/prune-stale-branches-current.mjs"), "verify", "--repo", root,
    "--contract-commit", inputs.current_contract.commit, "--contract", inputs.current_contract.path,
    "--allowlist-commit", inputs.allowlist.commit, "--allowlist", inputs.allowlist.path,
    "--verify-allowlist",
    "--stage", options.stage === "boundary" ? "boundary" : "before"];
  const missingReadinessSource = reasons.some((row) => row.code.startsWith("d01_readiness_source_commit_unavailable:"));
  let evidenceTransition = null;
  if (!missingReadinessSource) {
    if (options.sourceFixture) currentArgs.push("--source-fixture", safePath(options.sourceFixture));
    const current = spawnSync("node", currentArgs, { cwd: SCRIPT_ROOT, encoding: "utf8" });
    if (current.status !== 0) reasons.push({ code: `current_contract_verification_failed:${(current.stderr || current.stdout).trim().slice(0, 240)}` });
    else if (contract?.evidence_transition) {
      const marker = current.stdout.split(/\r?\n/).find((line) => line.startsWith("EVIDENCE_TRANSITION_JSON="));
      try { evidenceTransition = marker ? JSON.parse(marker.slice("EVIDENCE_TRANSITION_JSON=".length)) : null; } catch { evidenceTransition = null; }
      if (!evidenceTransition || evidenceTransition.contract_commit !== inputs.current_contract.commit) {
        reasons.push({ code: "current_contract_evidence_transition_receipt_missing_or_mismatched" });
      }
    }
  }

  const runtime = checkRuntime(reasons);
  checkCandidate(root, allowRows, options.candidateRef, reasons);
  const coordinator = checkCoordinator(root, options.stage, reasons);
  const after = { refs: refsFingerprint(root), worktrees: worktreeFingerprint(root), config: configFingerprint(root) };
  const equal = JSON.stringify(before) === JSON.stringify(after);
  if (!equal) reasons.push({ code: "admission_preflight_changed_repository_state" });
  return {
    schema_version: 1,
    repository_root: root,
    captured_at: new Date().toISOString(),
    stage: options.stage,
    status: reasons.length ? "blocked" : "admitted",
    current_contract: { commit: inputs.current_contract.commit, path: inputs.current_contract.path, blob: inputs.current_contract.blob, sha256: inputs.current_contract.sha256 },
    evidence_transition: evidenceTransition,
    inputs: Object.fromEntries(Object.entries(inputs).map(([key, row]) => [key, { commit: row.commit, path: row.path, blob: row.blob, sha256: row.sha256 }])),
    initial_admission: inputs.initial_admission ? { commit: inputs.initial_admission.commit, path: inputs.initial_admission.path, blob: inputs.initial_admission.blob, sha256: inputs.initial_admission.sha256 } : null,
    candidate_ref: options.candidateRef,
    candidate: allowRows.find((row) => row.side === "local" && row.ref === options.candidateRef) ?? null,
    runtime,
    coordinator,
    blocked_reasons: reasons,
    no_mutation: { refs_before: before.refs, refs_after: after.refs, worktrees_before: before.worktrees, worktrees_after: after.worktrees, config_before: before.config, config_after: after.config, equal },
  };
}

function parseArgs(argv) {
  const action = argv.shift();
  if (action === "coverage") {
    if (argv.length !== 2 || argv[0] !== "--repo") fail("usage", "coverage --repo PATH");
    return { action, repo: argv[1] };
  }
  if (!new Set(["capture", "verify"]).has(action)) fail("usage", "<capture|verify> --repo PATH ...");
  const options = { action, stage: "admission" };
  const seen = new Set();
  const names = new Map([
    ["--repo", "repo"], ["--current-contract-commit", "currentContractCommit"], ["--current-contract", "currentContract"],
    ["--snapshot-commit", "snapshotCommit"], ["--snapshot", "snapshot"], ["--origin-snapshot-commit", "originSnapshotCommit"], ["--origin-snapshot", "originSnapshot"],
    ["--allowlist-commit", "allowlistCommit"], ["--allowlist", "allowlist"], ["--readiness-commit", "readinessCommit"], ["--readiness", "readiness"],
    ["--source-fixture", "sourceFixture"], ["--candidate-ref", "candidateRef"], ["--output", "output"], ["--stage", "stage"],
    ["--admission", "admission"],
  ]);
  while (argv.length) {
    const key = argv.shift();
    const name = names.get(key);
    if (!name || !argv.length) fail("argument_invalid_or_missing_value", key);
    if (seen.has(name)) fail("argument_duplicate", key);
    seen.add(name);
    options[name] = argv.shift();
  }
  if (!options.repo) fail("repo_required");
  if (action === "capture" && !options.output) fail("output_required");
  if (action === "verify" && !new Set(["admission", "boundary", "after"]).has(options.stage)) fail("stage_invalid");
  if (action === "verify" && options.admission && !options.currentContractCommit) {
    const admissionPath = safePath(options.admission);
    let receipt;
    try { receipt = JSON.parse(readFileSync(path.resolve(options.repo, admissionPath), "utf8")); }
    catch { fail("initial_admission_receipt_unreadable", admissionPath); }
    const source = receipt?.verify_inputs;
    if (!source || typeof source !== "object") fail("initial_admission_verify_inputs_missing");
    options.currentContract = options.currentContract ?? safePath(source.current_contract?.path);
    options.currentContractCommit = source.current_contract?.commit === "self"
      ? git(options.repo, ["log", "-1", "--format=%H", "--", options.currentContract]).trim()
      : source.current_contract?.commit;
    options.snapshot = options.snapshot ?? safePath(source.local_snapshot?.path);
    options.snapshotCommit = options.snapshotCommit ?? source.local_snapshot?.commit;
    options.originSnapshot = options.originSnapshot ?? safePath(source.origin_snapshot?.path);
    options.originSnapshotCommit = options.originSnapshotCommit ?? source.origin_snapshot?.commit;
    options.allowlist = options.allowlist ?? safePath(source.allowlist?.path);
    options.allowlistCommit = options.allowlistCommit ?? (source.allowlist?.commit === "current_contract"
      ? options.currentContractCommit : source.allowlist?.commit);
    options.readiness = options.readiness ?? safePath(source.readiness?.path);
    options.readinessCommit = options.readinessCommit ?? source.readiness?.commit;
    options.sourceFixture = options.sourceFixture ?? (source.source_fixture ? safePath(source.source_fixture) : undefined);
    options.candidateRef = options.candidateRef ?? source.candidate_ref;
  }
  return options;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    const options = parseArgs(process.argv.slice(2));
    if (options.action === "coverage") {
      const findings = inspectMutationCoverage(options.repo);
      process.stdout.write(`${JSON.stringify({ status: findings.length ? "blocked" : "passed", findings }, null, 2)}\n`);
      if (findings.length) process.exitCode = 2;
    } else {
      const receipt = evaluate(options);
      const bytes = `${JSON.stringify(receipt, null, 2)}\n`;
      if (options.action === "capture") {
        const output = path.resolve(options.output);
        const temp = `${output}.tmp-${process.pid}`;
        writeFileSync(temp, bytes, { flag: "wx", mode: 0o600 });
        renameSync(temp, output);
      }
      process.stdout.write(bytes);
      if (receipt.status !== "admitted") process.exitCode = 2;
    }
  } catch (error) {
    process.stderr.write(`prune-stale-branches-admission: FAIL: ${error.message}\n`);
    process.exitCode = 2;
  }
}

