function validIntegrity(audit) {
  return {
    schema_version: 1,
    integrity_id: "fixture-integrity-245-07",
    outcome: "passed",
    audit: { audit_id: audit.audit_id, source_commit: "1".repeat(40), source_blob: "2".repeat(40) },
