    {
      name: 'chromium',
      testIgnore: [ADMIN_CHECKPOINTS_SPEC, ADMIN_DESIGN_SPEC, ADMIN_GENERATED_SPEC, GENERATED_CONFIRMATION_SPEC, DEMO_SHOWCASE_SPEC, ADMIN_EVAL_SPEC],
