      testIgnore: [
        ADMIN_BEHAVIOR_SPECS,
        ADMIN_CHECKPOINTS_SPEC,
        ADMIN_DESIGN_SPEC,
        ADMIN_GENERATED_SPEC,
        GENERATED_CONFIRMATION_SPEC,
        WEBAUTHN_CDP_SPECS,
        DEMO_SHOWCASE_SPEC,
        ADMIN_MODAL_SPEC,
        ADMIN_EVAL_SPEC,
      ],
      use: { ...devices['iPhone 13'] },
    },
    // Admin checkpoint lane (chromium desktop): reviewer-facing curated
