import { defineConfig } from '@playwright/test';
import productionConfig from './playwright.config';

// Phase 253 plan 39: scoped per-project selection for the four remaining native
// registration-control windows. Everything the production config decides (device and
// theme presets, `use`, workers, fullyParallel, retries, timeouts, expect, reporters,
// test directory and output directory) is inherited unchanged; this file only
// narrows the three admin-eval projects and gives EACH project its own title filter.
//
// The CLI must never pass --grep, because a CLI grep would replace these per-project
// filters. The stage flag is opt-in and mandatory here: the controls it enables are
// declared by tests/admin-eval.spec.ts only for the matching stage, so an unset or
// unknown stage fails closed instead of silently running an empty or wrong inventory.

const SPEC_PROJECTS = ['admin-eval', 'admin-eval-mobile', 'admin-eval-dark'] as const;

const FIRST_TITLES = [
  'registration waits for explicitly released LiveView readiness',
  'registration stops when LiveView readiness is never released',
  'registration fails when the readiness wait is deliberately broken',
  'registration detects a deliberate same-account collision',
  'registration retains the first forced assertion failure trace',
];
const SECOND_TITLES = [
  'registration starts from a fresh database and context',
  'registration discards trace after a passing control',
];
const ORIGINAL_BOARD_TITLE = 'render bundle: board-mg-9/populated';

const stage = process.env.SIGRA_REGISTRATION_CONTROL_STAGE;
if (stage !== 'first' && stage !== 'second') {
  throw new Error(
    `playwright.registration-recovery.config.ts requires SIGRA_REGISTRATION_CONTROL_STAGE=first|second (got ${stage ?? 'unset'})`,
  );
}

const escapeRegExp = (value: string) => value.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&');
const exactTitles = (titles: string[]) => new RegExp(`(${titles.map(escapeRegExp).join('|')})`);

function titlesFor(projectName: string): string[] {
  if (stage === 'second') return SECOND_TITLES;
  // The original board rows are part of the single first command, in dark only.
  return projectName === 'admin-eval-dark' ? [ORIGINAL_BOARD_TITLE, ...FIRST_TITLES] : FIRST_TITLES;
}

const projects = productionConfig.projects ?? [];
const selected = SPEC_PROJECTS.map((name) => {
  const project = projects.find((candidate) => candidate.name === name);
  if (!project) throw new Error(`production config no longer defines the ${name} project`);
  return { ...project, grep: exactTitles(titlesFor(name)) };
});

export default defineConfig({
  ...productionConfig,
  projects: selected,
});

import { readFile } from 'node:fs/promises';
import { test, expect, type Download, type Page } from '@playwright/test';
import { adminUsersEmailLocator } from '../helpers/adminUsersIndex';
import { TEST_PASSWORD } from '../helpers/fixtures';

// Phase 31 Plan 2: canonical admin audit browser contract.
//
// Per D-01, D-02, D-04 (4), D-19, D-20, and D-26 this spec owns:
//   * /admin/audit filter + visible impersonation semantics
//   * /admin/audit/export.csv global CSV download
//   * /admin/organizations/:slug/users/:id/audit filter alignment + per-user
//     scoped CSV download
//
// Per D-06 this spec does NOT absorb the malformed-param, scope-safe export,
// audit attribution, or authorization-permutation matrices; those stay in
// ExUnit (test/sigra/admin/audit/query_test.exs,
// test/example/test/example_web/controllers/admin/audit_export_controller_test.exs).
// Download contents are asserted for semantic markers only — not exact
// file bodies — per the `admin-audit` download/assert pattern documented in
// `.planning/phases/31-automation-first-verification/31-PATTERNS.md`. Per
// D-27 this spec only runs on the `chromium` behavior-truth lane; curated
// audit explorer screenshots live in `tests/admin-checkpoints.spec.ts`.

async function waitForLiveViewReady(page: Page) {
  await page.waitForSelector('[data-phx-session].phx-connected', {
    state: 'attached',
  });
}

async function registerUser(page: Page, email: string, password: string) {
  await page.goto('/users/register');
  await waitForLiveViewReady(page);
  await page.fill('input[name="user[email]"]', email);
  await page.fill('input[name="user[password]"]', password);
  await page.locator('form:has(input[name="user[password]"])').first().evaluate((form) => {
    (form as HTMLFormElement).requestSubmit();
  });
  await expect(page).not.toHaveURL(/\/users\/register/);
}

async function clearBrowserSession(page: Page) {
  await page.context().clearCookies();
}

async function createOrganization(page: Page, name: string, slug: string) {
  await page.goto('/organizations');
  await waitForLiveViewReady(page);
  await page.fill('input[name="organization[name]"]', name);
  await expect(page.locator('#slug-preview')).toHaveText(slug);
  await page.click('button:has-text("Create organization")');
  await expect(page).toHaveURL(new RegExp(`/organizations/${slug}$|/organizations/${slug}/members$`));
  await waitForLiveViewReady(page);
}

async function openUserDetail(page: Page, targetEmail: string) {
  await page.goto(`/admin/users?q=${encodeURIComponent(targetEmail)}`);
  await waitForLiveViewReady(page);
  await expect(adminUsersEmailLocator(page, targetEmail)).toBeVisible();
  await page.getByRole('link', { name: 'Open user' }).first().click();
  await waitForLiveViewReady(page);
  await expect(page).toHaveURL(/\/admin\/users\/[^?]+/);
}

async function confirmSudo(page: Page, password: string) {
  await expect(page).toHaveURL(/\/users\/sudo\?/);
  await page.fill('input[name="sudo[password]"]', password);
  await page.getByRole('button', { name: 'Confirm password' }).click();
}

async function readDownload(download: Download) {
  const path = await download.path();
  expect(path).not.toBeNull();
  return await readFile(path as string, 'utf8');
}

test.describe('Phase 31 admin audit browser contract (D-04 4)', () => {
  test('global investigation and org-scoped per-user export keep filter semantics aligned', async ({
    page,
    browser,
  }) => {
    const suffix = Date.now();
    const password = TEST_PASSWORD;
    const targetEmail = `audit-target-${suffix}@example.test`;
    const adminEmail = `platform-admin+audit-${suffix}@example.test`;
    const orgName = `Audit Org ${suffix}`;
    const orgSlug = `audit-org-${suffix}`;

    await registerUser(page, targetEmail, password);
    await createOrganization(page, orgName, orgSlug);
    await clearBrowserSession(page);
    await registerUser(page, adminEmail, password);

    await openUserDetail(page, targetEmail);

    const detailUrl = new URL(page.url());
    const detailPath = `${detailUrl.pathname}${detailUrl.search}`;
    await page.goto(`/users/sudo?return_to=${encodeURIComponent(detailPath)}`);
    await confirmSudo(page, password);
    await waitForLiveViewReady(page);

    await page.getByRole('button', { name: 'Start impersonation' }).click();
    await expect(page).toHaveURL('/');

    await page.goto(`/organizations/${orgSlug}/members`);
    await waitForLiveViewReady(page);
    await expect(page.getByRole('button', { name: 'End impersonation' })).toBeVisible();
    await page.getByRole('button', { name: 'End impersonation' }).click();
    await expect(page).toHaveURL(/\/admin\/users\?.*q=/);
    await waitForLiveViewReady(page);

    await page.goto('/admin/audit?action_prefix=admin.impersonation');
    await waitForLiveViewReady(page);
    await expect(page.getByRole('heading', { name: 'Audit' })).toBeVisible();
    await expect(page.getByText('Impersonation').first()).toBeVisible();
    await expect(page.getByText('acting as').first()).toBeVisible();

    // The first submit adds the canonical sort/page defaults. Repeating that
    // submit must then preserve both its canonical URL and rendered rows.
    await page.getByRole('textbox', { name: 'Action prefix' }).fill('admin.impersonation');
    await page.getByRole('button', { name: 'Apply filters' }).click();
    await expect(page).toHaveURL((url) =>
      url.pathname === '/admin/audit' &&
      url.searchParams.get('action_prefix') === 'admin.impersonation' &&
      url.searchParams.get('order_by') === 'inserted_at' &&
      url.searchParams.get('order_direction') === 'desc' &&
      url.searchParams.get('page_size') === '25',
    );
    await waitForLiveViewReady(page);
    const connectedAuditUrl = page.url();
    const connectedRows = await page
      .locator('#admin-audit-desktop-results tbody tr')
      .allInnerTexts();
    await page.getByRole('button', { name: 'Apply filters' }).click();
    await expect(page.locator('form.phx-submit-loading')).toHaveCount(0);
    await waitForLiveViewReady(page);
    await expect(page).toHaveURL(connectedAuditUrl);
    await expect(page.locator('#admin-audit-desktop-results tbody tr')).toHaveText(connectedRows, { useInnerText: true });

    // JavaScript disabled gives a deterministic pre-connect path: the
    // disconnected server-rendered form must submit through its native GET
    // action and produce the same filtered rows as the connected patch path.
    const noJavaScriptContext = await browser.newContext({
      javaScriptEnabled: false,
    });
    await noJavaScriptContext.addCookies(await page.context().cookies());
    const noJavaScriptPage = await noJavaScriptContext.newPage();
    const baseUrl = new URL(page.url()).origin;
    await noJavaScriptPage.goto(new URL('/admin/audit', baseUrl).toString());
    await expect(
      noJavaScriptPage.locator('[data-phx-session].phx-connected'),
    ).toHaveCount(0);
    await noJavaScriptPage
      .getByRole('textbox', { name: 'Action prefix' })
      .fill('admin.impersonation');
    await noJavaScriptPage
      .getByRole('button', { name: 'Apply filters' })
      .click();
    await expect(noJavaScriptPage).toHaveURL(/\/admin\/audit\?/);
    await expect(
      noJavaScriptPage.getByRole('textbox', { name: 'Action prefix' }),
    ).toHaveValue('admin.impersonation');
    expect(
      await noJavaScriptPage
        .locator('#admin-audit-desktop-results tbody tr')
        .allInnerTexts(),
    ).toEqual(connectedRows);
    await noJavaScriptContext.close();

    const globalDownload = page.waitForEvent('download');
    await page.getByRole('link', { name: 'Export CSV' }).click();
    const globalCsv = await readDownload(await globalDownload);

    expect(globalCsv).toContain('impersonation_state');
    expect(globalCsv).toContain('admin.impersonation.start');
    expect(globalCsv).toContain(targetEmail);
    expect(globalCsv).toContain(adminEmail);

    await openUserDetail(page, targetEmail);
    await page.getByRole('link', { name: new RegExp(`Open organization-scoped view for ${orgName}`) }).click();
    await waitForLiveViewReady(page);
    await expect(page).toHaveURL(new RegExp(`/admin/organizations/${orgSlug}/users/[^/]+`));

    await page.getByRole('link', { name: 'View full audit' }).click();
    await waitForLiveViewReady(page);
